/* ---------- Autosave ---------- */
let _quizAutosaveTimer = null;
function startQuizAutosave() {
  stopQuizAutosave();
  _quizAutosaveTimer = setInterval(() => {
    if (!quizEditingCourseId || !quizEditingMaterialId) return;
    try {
      const payload = {
        courseId:   quizEditingCourseId,
        materialId: quizEditingMaterialId,
        config: {
          subject:    ($('qpSubject')?.value || ''),
          paperCode:  ($('qpCode')?.value    || ''),
          totalTime:  ($('qpTime')?.value    || ''),
          totalMarks: parseInt($('qpMarks')?.value, 10) || 0
        },
        quiz: quizDraft,
        savedAt: Date.now()
      };
      localStorage.setItem('aero_quiz_draft_' + quizEditingMaterialId, JSON.stringify(payload));
    } catch (e) {}
  }, 15000);
}
function stopQuizAutosave() {
  if (_quizAutosaveTimer) { clearInterval(_quizAutosaveTimer); _quizAutosaveTimer = null; }
}
function getSavedQuizDraft(materialId) {
  try {
    const raw = localStorage.getItem('aero_quiz_draft_' + materialId);
    if (!raw) return null;
    const data = JSON.parse(raw);
    if (!data || !data.savedAt) return null;
    if (Date.now() - data.savedAt > 24 * 60 * 60 * 1000) {
      localStorage.removeItem('aero_quiz_draft_' + materialId);
      return null;
    }
    return data;
  } catch { return null; }
}
function clearSavedQuizDraft(materialId) {
  try { localStorage.removeItem('aero_quiz_draft_' + materialId); } catch {}
}

/* ---------- Student answer persistence ---------- */
function persistQuizAnswers() {
  const st = quizPlayerState;
  if (!st || st.previewMode || st.submitted) return;
  try {
    localStorage.setItem('aero_quiz_answers_' + st.materialId, JSON.stringify(st.answers));
  } catch {}
}
function restoreQuizAnswers(materialId) {
  try {
    const raw = localStorage.getItem('aero_quiz_answers_' + materialId);
    return raw ? JSON.parse(raw) : null;
  } catch { return null; }
}
function clearQuizAnswers(materialId) {
  try { localStorage.removeItem('aero_quiz_answers_' + materialId); } catch {}
}

/* ---------- Student test timer ---------- */
let _quizTimerHandle = null;
function parseQuizTime(s) {
  if (!s) return 0;
  s = String(s).toLowerCase().trim();
  const hm = s.match(/(\d+)\s*h(?:our|r)?s?/);
  const mm = s.match(/(\d+)\s*m(?:in(?:ute)?)?s?/);
  let sec = 0;
  if (hm) sec += parseInt(hm[1], 10) * 3600;
  if (mm) sec += parseInt(mm[1], 10) * 60;
  if (!sec) {
    const justN = s.match(/^(\d+)$/);
    if (justN) sec = parseInt(justN[1], 10) * 60;
  }
  return sec;
}
function formatDuration(sec) {
  const h = Math.floor(sec / 3600);
  const m = Math.floor((sec % 3600) / 60);
  const s = sec % 60;
  return (h > 0 ? String(h).padStart(2, '0') + ':' : '')
       + String(m).padStart(2, '0') + ':' + String(s).padStart(2, '0');
}
function startQuizTimer() {
  stopQuizTimer();
  const st = quizPlayerState;
  if (!st || st.previewMode || st.submitted) return;
  const duration = parseQuizTime(st.paperConfig && st.paperConfig.totalTime);
  if (!duration) return;

  const startKey = 'aero_quiz_start_' + st.materialId;
  let startedAt = parseInt(localStorage.getItem(startKey), 10);
  if (!startedAt) {
    startedAt = Date.now();
    localStorage.setItem(startKey, String(startedAt));
  }

  const tick = () => {
    const elapsed = Math.floor((Date.now() - startedAt) / 1000);
    const remaining = Math.max(0, duration - elapsed);
    const el = document.getElementById('quizTimerDisplay');
    if (el) {
      el.textContent = formatDuration(remaining);
      el.classList.toggle('warning', remaining < 60 && remaining > 0);
      el.classList.toggle('expired', remaining === 0);
    }
    if (remaining === 0) {
      stopQuizTimer();
      try { showToast('⏰ Time is up!', 'error'); } catch (e) {}
      submitQuiz();
    }
  };
  tick();
  _quizTimerHandle = setInterval(tick, 1000);
}
function stopQuizTimer() {
  if (_quizTimerHandle) { clearInterval(_quizTimerHandle); _quizTimerHandle = null; }
  const el = document.getElementById('quizTimerDisplay');
  if (el) el.classList.remove('warning', 'expired');
}

/* ---------- Preview HTML escaper ---------- */
function escapeForPreview(s) {
  return String(s == null ? '' : s)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

/* ---------- Preview box helper ---------- */
function latexPreviewBox(id, initialValue) {
  const isEmpty = !initialValue || !String(initialValue).trim();
  return `<div class="latex-preview ${isEmpty ? 'is-empty' : ''}" id="latex-preview-${id}">${escapeForPreview(initialValue || '')}</div>`;
}

/* ---------- Keyboard Ctrl+S for quiz editor ---------- */
document.addEventListener('keydown', (e) => {
  if (!quizEditingCourseId) return;
  if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === 's') {
    e.preventDefault();
    saveQuizPaper();
  }
});

/* ============================================================
   QUIZ EDITOR — Full-page open / close / render
   ============================================================ */
async function openQuizEditor(courseId, materialId) {
  const course = findCourse(courseId);
  if (!course) return showToast('Course not found.', 'error');
  const mat = (course.materials || []).find(m => m.id === materialId);
  if (!mat) return showToast('Material not found.', 'error');

  // ─── CRITICAL FIX: load the full quiz array if it hasn't been loaded yet.
  // The /api/courses list strips `quiz` for perf — only `quizCount` arrives.
  // Without this fetch, the editor would open with zero questions.
  if (!Array.isArray(mat.quiz)) {
    const hasQuestions = (mat.quizCount || 0) > 0;
    if (hasQuestions) {
      try {
        showToast('Loading question paper…', 'info');
        const res = await fetch(
          `${API_BASE}/courses/${courseId}/materials/${materialId}/full-quiz?_t=${Date.now()}`
        );
        const data = await res.json();
        mat.quiz = (data && data.success && Array.isArray(data.quiz)) ? data.quiz : [];
        mat.examConfig = (data && data.examConfig) || mat.examConfig || {};
      } catch (e) {
        console.warn('[openQuizEditor] full-quiz fetch failed:', e);
        mat.quiz = [];
        showToast('Could not load existing questions — starting fresh.', 'error');
      }
    } else {
      mat.quiz = [];
    }
  }

  quizEditingCourseId = courseId;
  quizEditingMaterialId = materialId;

  const saved = getSavedQuizDraft(materialId);
  let useSaved = false;
  if (saved && Array.isArray(saved.quiz) && saved.quiz.length > 0) {
    const ageMin = Math.round((Date.now() - saved.savedAt) / 60000);
    useSaved = confirm(
      `An unsaved draft was autosaved ${ageMin} minute${ageMin === 1 ? '' : 's'} ago.\n\n` +
      `Restore it?\n\n[OK] Restore draft\n[Cancel] Discard and use the last SAVED version`
    );
  }

  if (useSaved) {
    quizDraft = saved.quiz.map(q => normalizeQuestion(q));
    const sc = saved.config || {};
    quizPaperConfig = {
      subject:    sc.subject    || '',
      paperCode:  sc.paperCode  || '',
      totalTime:  sc.totalTime  || '',
      totalMarks: Number(sc.totalMarks) || 0,
      allowBackNavigation:  sc.allowBackNavigation  === true,
      showQuestionPalette:  sc.showQuestionPalette !== false,
      /* ⭐ NEW */
      maxAttempts:             Number(sc.maxAttempts) || 0,
      resultPublishMode:       sc.resultPublishMode   || 'immediate',
      resultPublishAt:         sc.resultPublishAt     || null,
      resultPublishDelayHours: Number(sc.resultPublishDelayHours) || 0,
      resultsPublished:        sc.resultsPublished === true
    };
  } else {
    const rawQuiz = Array.isArray(mat.quiz) ? mat.quiz : [];
    quizDraft = rawQuiz.map(q => normalizeQuestion(q));
    const cfg = mat.examConfig || {};
    quizPaperConfig = {
      subject:    cfg.subject    || course.name    || '',
      paperCode:  cfg.paperCode  || (course.code ? course.code + '-' + (mat.title || '') : ''),
      totalTime:  cfg.totalTime  || '',
      totalMarks: Number(cfg.totalMarks) || quizDraft.reduce((s, q) => s + (q.marks || 0), 0),
      allowBackNavigation:  cfg.allowBackNavigation === true,
      showQuestionPalette:  cfg.showQuestionPalette !== false,
      /* ⭐ NEW */
      maxAttempts:             Number(cfg.maxAttempts) || 0,
      resultPublishMode:       cfg.resultPublishMode   || 'immediate',
      resultPublishAt:         cfg.resultPublishAt     || null,
      resultPublishDelayHours: Number(cfg.resultPublishDelayHours) || 0,
      resultsPublished:        cfg.resultsPublished === true
    };
  }

  addingCourse = false; addingProfessor = false;
  addingMaterialCourseId = null; addingStudent = false;
  editingCourseId = null; currentCourseId = null;
  window.currentSelectedCourseId = null;

  pushHash(`#/admin/quiz/${courseId}/${materialId}`);
  renderApp();
}

function closeQuizEditor() {
  const hasDraft = quizDraft.length > 0;
  if (hasDraft) {
    const ok = confirm('Close the paper editor?\n\nYour unsaved changes are autosaved locally and will be offered for restore next time.');
    if (!ok) return;
  }
  stopQuizAutosave();
  const cid = quizEditingCourseId;
  quizEditingCourseId = null;
  quizEditingMaterialId = null;
  quizDraft = [];
  if (cid) openCourseEditor(cid);
  else { pushHash('#/admin/courses'); renderApp(); }
}

function normalizeQuestion(q) {
  const type = q.type || (Array.isArray(q.correctIndexes) && q.correctIndexes.length > 1
    ? 'multiple' : 'single');

  let correctIndexes = Array.isArray(q.correctIndexes) ? [...q.correctIndexes]
    : (typeof q.correctIndex === 'number' ? [q.correctIndex] : []);

  const numOrNull = (v) => (v === null || v === undefined || v === '') ? null : Number(v);

  return {
    type,
    question:    q.question    || '',
    explanation: q.explanation || '',

    options:        (q.options && q.options.length) ? [...q.options] : ['', '', '', ''],
    correctIndexes,

    integerAnswer:    numOrNull(q.integerAnswer),
    integerTolerance: Number(q.integerTolerance) || 0,

    /* ⭐ NEW: Numerical Range */
    rangeMin: numOrNull(q.rangeMin),
    rangeMax: numOrNull(q.rangeMax),

    /* ⭐ NEW: Subjective */
    subjectiveMaxMarks:     Number(q.subjectiveMaxMarks) || 10,
    subjectiveInstructions: q.subjectiveInstructions || '',

    matrixLeftItems:  (q.matrixLeftItems && q.matrixLeftItems.length) ? [...q.matrixLeftItems] : ['', '', '', ''],
    matrixRightItems: (q.matrixRightItems && q.matrixRightItems.length) ? [...q.matrixRightItems] : ['', '', '', ''],
    matrixRows:       Array.isArray(q.matrixRows) && q.matrixRows.length
      ? q.matrixRows.map(r => ({ text: r.text || '', correctIndex: Number(r.correctIndex) || 0 }))
      : [ { text: '', correctIndex: 0 }, { text: '', correctIndex: 1 },
          { text: '', correctIndex: 2 }, { text: '', correctIndex: 3 } ],

    marks:         typeof q.marks === 'number' ? q.marks : 4,
    negativeMarks: typeof q.negativeMarks === 'number' ? q.negativeMarks : -1
  };
}

/* ============================================================
   QUIZ EDITOR — Render (with live preview + reorder + autosave)
   ============================================================ */
let _quizEditorLoading = false;
/* ============================================================
   QUIZ RESULT SCHEDULING — UI HELPERS
   ------------------------------------------------------------
   These three helpers are called by renderQuizEditor() when the
   admin opens the paper editor. Without them the schedule fields
   never show / hide and "Publish Now" throws "not a function".
   ============================================================ */

/* Format a Date / ISO string into the value format a
   <input type="datetime-local"> expects: "YYYY-MM-DDTHH:MM" */
function toDateTimeLocalValue(dateInput) {
  if (!dateInput) return '';
  try {
    const d = new Date(dateInput);
    if (isNaN(d.getTime())) return '';
    const pad = (n) => String(n).padStart(2, '0');
    return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}` +
           `T${pad(d.getHours())}:${pad(d.getMinutes())}`;
  } catch (e) {
    return '';
  }
}

/* Show / hide the schedule sub-panel and the manual-publish box
   depending on which result mode the admin selected. */
function onQuizResultModeChange() {
  const mode = ($('qpResultMode')?.value || 'immediate');
  const scheduleWrap   = $('qpScheduleWrap');
  const publishActions = $('qpPublishActions');
  if (scheduleWrap)   scheduleWrap.style.display   = (mode === 'scheduled') ? 'block' : 'none';
  if (publishActions) publishActions.style.display = (mode === 'manual')    ? 'block' : 'none';
}

/* Admin override — release results now, bypassing any schedule.
   Calls POST /api/admin/quiz/:courseId/:materialId/publish-now  */
async function publishQuizResultsNow() {
  if (!quizEditingCourseId || !quizEditingMaterialId) {
    return showToast('No quiz is open.', 'error');
  }
  if (!confirm(
    'Release every submitted result NOW and notify every student?\n\n' +
    'This also switches this paper back to "Immediate" mode, so any ' +
    'student who submits later sees their score straight away.'
  )) return;

  const btn = document.querySelector('button[onclick="publishQuizResultsNow()"]');
  const orig = btn ? btn.innerHTML : '';
  if (btn) {
    btn.disabled = true;
    btn.innerHTML = '<i class="fas fa-spinner fa-spin"></i> Publishing…';
  }

  try {
    const res = await fetch(
      `/api/admin/quiz/${quizEditingCourseId}/${quizEditingMaterialId}/publish-now`,
      { method: 'POST', headers: { 'Content-Type': 'application/json' } }
    );
    const data = await res.json();

    if (data && data.success) {
      showToast('✅ ' + (data.message || 'Results published.'), 'success');

      /* Reflect the new state in the open editor */
      quizPaperConfig.resultPublishMode = 'immediate';
      quizPaperConfig.resultsPublished  = true;
      const modeEl = $('qpResultMode');
      if (modeEl) modeEl.value = 'immediate';
      onQuizResultModeChange();
    } else {
      showToast((data && data.message) || 'Failed to publish.', 'error');
    }
  } catch (err) {
    console.error('[publishQuizResultsNow]', err);
    showToast('Network error while publishing.', 'error');
  } finally {
    if (btn) {
      btn.disabled = false;
      btn.innerHTML = orig || '<i class="fas fa-bullhorn"></i> Publish Results Now';
    }
  }
}
async function renderQuizEditor() {
  const container = document.getElementById('quizEditorContent');
  if (!container) return;
  const course = findCourse(quizEditingCourseId);
  if (!course) { container.innerHTML = '<p>Course not found.</p>'; return; }
  const mat = (course.materials || []).find(m => m.id === quizEditingMaterialId);
  if (!mat) { container.innerHTML = '<p>Material not found.</p>'; return; }

  // ─── Direct-URL access path: if the quiz array isn't loaded yet, fetch it.
  if (!Array.isArray(mat.quiz) && (mat.quizCount || 0) > 0 && !_quizEditorLoading) {
    _quizEditorLoading = true;
    container.innerHTML = `
      <div class="courses-loading">
        <div class="pdfv-spinner"></div>
        <p>Loading question paper…</p>
      </div>`;
    try {
      const res = await fetch(
        `${API_BASE}/courses/${quizEditingCourseId}/materials/${quizEditingMaterialId}/full-quiz?_t=${Date.now()}`
      );
      const data = await res.json();
      mat.quiz = (data && data.success && Array.isArray(data.quiz)) ? data.quiz : [];
      mat.examConfig = (data && data.examConfig) || mat.examConfig || {};
    } catch (e) {
      console.warn('[renderQuizEditor] fetch failed:', e);
      mat.quiz = [];
    } finally {
      _quizEditorLoading = false;
    }

    const saved = getSavedQuizDraft(quizEditingMaterialId);
    if (saved && Array.isArray(saved.quiz) && saved.quiz.length > 0) {
      quizDraft = saved.quiz.map(q => normalizeQuestion(q));
      const sc = saved.config || {};
      quizPaperConfig = {
        subject:    sc.subject    || '',
        paperCode:  sc.paperCode  || '',
        totalTime:  sc.totalTime  || '',
        totalMarks: Number(sc.totalMarks) || 0,
        allowBackNavigation: sc.allowBackNavigation === true,
        showQuestionPalette: sc.showQuestionPalette !== false,
        maxAttempts:             Number(sc.maxAttempts) || 0,
        resultPublishMode:       sc.resultPublishMode   || 'immediate',
        resultPublishAt:         sc.resultPublishAt     || null,
        resultPublishDelayHours: Number(sc.resultPublishDelayHours) || 0,
        resultsPublished:        sc.resultsPublished === true
      };
    } else {
      quizDraft = (mat.quiz || []).map(q => normalizeQuestion(q));
      const cfg = mat.examConfig || {};
      quizPaperConfig = {
        subject:    cfg.subject    || course.name || '',
        paperCode:  cfg.paperCode  || (course.code ? course.code + '-' + (mat.title || '') : ''),
        totalTime:  cfg.totalTime  || '',
        totalMarks: Number(cfg.totalMarks) || quizDraft.reduce((s, q) => s + (q.marks || 0), 0),
        allowBackNavigation: cfg.allowBackNavigation === true,
        showQuestionPalette: cfg.showQuestionPalette !== false,
        maxAttempts:             Number(cfg.maxAttempts) || 0,
        resultPublishMode:       cfg.resultPublishMode   || 'immediate',
        resultPublishAt:         cfg.resultPublishAt     || null,
        resultPublishDelayHours: Number(cfg.resultPublishDelayHours) || 0,
        resultsPublished:        cfg.resultsPublished === true
      };
    }
  }

  const autoTotal = quizDraft.reduce((s, q) => s + (Number(q.marks) || 0), 0);

  container.innerHTML = `
    <button class="back-link" onclick="closeQuizEditor()">
      <i class="fas fa-arrow-left"></i> Back to Course Editor
    </button>

    <div class="dash-header">
      <h2><i class="fas fa-file-pen"></i> Question Paper Editor</h2>
      <div class="actions">
        <button class="btn btn-outline" onclick="toggleLatexPreviews()" id="previewToggleBtn">
          <i class="fas fa-eye"></i> Hide Previews
        </button>
        <button class="btn btn-outline" onclick="previewQuizPaper()">
          <i class="fas fa-eye"></i> Preview as Student
        </button>
        <button class="btn btn-primary" onclick="saveQuizPaper()" id="quizSaveBtn">
          <i class="fas fa-save"></i> Save Paper
          <span style="opacity:.7;font-size:11px;margin-left:6px;">(Ctrl+S)</span>
        </button>
      </div>
    </div>

    <div class="editor-section">
      <div class="editor-section-title">
        <i class="fas fa-info-circle"></i> Paper Details
        <span style="font-size:12px;color:var(--text-tertiary);font-weight:500;margin-left:8px;">
          ${escapeHtml(course.name)} · ${escapeHtml(mat.title)}
        </span>
      </div>
      <div class="editor-grid-2">
        <div class="form-group">
          <label>Subject Name</label>
          <input type="text" id="qpSubject" value="${escapeHtml(quizPaperConfig.subject)}" placeholder="e.g. Physics">
        </div>
        <div class="form-group">
          <label>Paper Code</label>
          <input type="text" id="qpCode" value="${escapeHtml(quizPaperConfig.paperCode)}" placeholder="e.g. AE101-MID">
        </div>
        <div class="form-group">
          <label>Total Time Duration</label>
          <input type="text" id="qpTime" value="${escapeHtml(quizPaperConfig.totalTime)}" placeholder="e.g. 3 hours or 90 min">
          <span class="hint">Auto-parsed for countdown timer (e.g. "1.5 hours", "90 min", "120").</span>
        </div>
        <div class="form-group">
          <label>Total Marks</label>
          <input type="number" id="qpMarks" value="${quizPaperConfig.totalMarks || autoTotal}" min="0" step="1" placeholder="e.g. 100">
          <span class="hint">Auto-computed from questions: <strong id="qpAutoHint">${autoTotal}</strong></span>
        </div>
      </div>
    </div>

    <!-- ⭐ ATTEMPT LIMITS & SCHEDULED RESULT PUBLICATION -->
    <div class="editor-section">
      <div class="editor-section-title">
        <i class="fas fa-clock-rotate-left"></i> Attempts &amp; Result Publication
      </div>

      <div class="editor-grid-2">
        <div class="form-group">
          <label>Maximum Attempts Allowed</label>
          <input type="number" id="qpMaxAttempts"
                 value="${Number(quizPaperConfig.maxAttempts) || 0}"
                 min="0" max="99" step="1"
                 placeholder="0 = unlimited">
          <span class="hint">
            <strong>0 = unlimited.</strong> Once a student has submitted
            this many attempts, the Start / Retake button is disabled
            and they are told the test is finished.
          </span>
        </div>

        <div class="form-group">
          <label>Result Publication</label>
          <select id="qpResultMode" onchange="onQuizResultModeChange()">
            <option value="immediate" ${quizPaperConfig.resultPublishMode === 'immediate' ? 'selected' : ''}>Immediate — show score right after submit</option>
            <option value="scheduled" ${quizPaperConfig.resultPublishMode === 'scheduled' ? 'selected' : ''}>Scheduled — hide until a set time</option>
            <option value="manual"    ${quizPaperConfig.resultPublishMode === 'manual'    ? 'selected' : ''}>Manual — hide until you click “Publish Now”</option>
          </select>
          <span class="hint">
            Controls when students see their score. The score is always
            computed and saved; only the <em>visibility</em> is delayed.
          </span>
        </div>
      </div>

      <div id="qpScheduleWrap" style="display:${quizPaperConfig.resultPublishMode === 'scheduled' ? 'block' : 'none'}; margin-top:6px;">
        <div class="editor-grid-2">
          <div class="form-group">
            <label>Publish On (absolute)</label>
            <input type="datetime-local" id="qpPublishAt"
                   value="${toDateTimeLocalValue(quizPaperConfig.resultPublishAt)}">
            <span class="hint">Wins over the delay option below when both are set. Leave blank to use the delay.</span>
          </div>
          <div class="form-group">
            <label>Or, Publish After Each Student Submits (hours)</label>
            <input type="number" id="qpPublishDelayHours"
                   value="${Number(quizPaperConfig.resultPublishDelayHours) || 0}"
                   min="0" max="8760" step="1" placeholder="0">
            <span class="hint">Per-student delay. <strong>0 = ignore.</strong> Example: 48 → each student sees their score 48 hours after they submit.</span>
          </div>
        </div>
      </div>

      <div id="qpPublishActions" style="display:${quizPaperConfig.resultPublishMode === 'manual' ? 'block' : 'none'}; margin-top:14px; padding:14px 16px; background:linear-gradient(135deg, rgba(245,158,11,.10), rgba(251,191,36,.03)); border:1.5px solid rgba(245,158,11,.35); border-radius:var(--radius-md);">
        <div style="display:flex; justify-content:space-between; align-items:center; gap:12px; flex-wrap:wrap;">
          <div>
            <strong style="display:block; font-size:13.5px; color:var(--text-primary); margin-bottom:3px;">
              <i class="fas fa-bullhorn" style="color:var(--gold-500);"></i>
              Manual Release
            </strong>
            <span style="font-size:12.5px; color:var(--text-tertiary);">
              Release every submitted result now and notify every student.
            </span>
          </div>
          <button type="button" class="btn btn-warning"
                  onclick="publishQuizResultsNow()"
                  style="flex-shrink:0;">
            <i class="fas fa-bullhorn"></i> Publish Results Now
          </button>
        </div>
      </div>
      <div class="quiz-nav-policy">
        <div class="quiz-nav-policy-head">
          <i class="fas fa-compass"></i>
          <div>
            <strong>Navigation Policy</strong>
            <span>Controls what students can do between questions.</span>
          </div>
        </div>

        <label class="quiz-nav-option ${!quizPaperConfig.allowBackNavigation ? 'active' : ''}"
               id="qpNavStrictLabel">
          <input type="radio" name="qpNavPolicy" value="strict"
                 ${!quizPaperConfig.allowBackNavigation ? 'checked' : ''}
                 onchange="onQuizNavPolicyChange()">
          <div class="quiz-nav-option-body">
            <div class="quiz-nav-option-title">
              <i class="fas fa-lock"></i>
              Strict — Forward-only
            </div>
            <div class="quiz-nav-option-desc">
              Students answer one question at a time and cannot return. The
              <strong>Previous</strong> button is hidden and earlier questions are locked in the palette.
              Best for high-stakes exams.
            </div>
          </div>
        </label>

        <label class="quiz-nav-option ${quizPaperConfig.allowBackNavigation ? 'active' : ''}"
               id="qpNavFlexLabel">
          <input type="radio" name="qpNavPolicy" value="flexible"
                 ${quizPaperConfig.allowBackNavigation ? 'checked' : ''}
                 onchange="onQuizNavPolicyChange()">
          <div class="quiz-nav-option-body">
            <div class="quiz-nav-option-title">
              <i class="fas fa-arrows-left-right"></i>
              Flexible — Free navigation
            </div>
            <div class="quiz-nav-option-desc">
              Students may jump to any question from the palette, use
              <strong>Previous</strong> to go back, and change answers before submitting.
              Best for practice tests.
            </div>
          </div>
        </label>

        <label class="quiz-nav-toggle quiz-nav-toggle-inline">
          <input type="checkbox" id="qpShowPalette"
                 ${quizPaperConfig.showQuestionPalette !== false ? 'checked' : ''}>
          <span>Show the numbered question palette to students</span>
        </label>
      </div>
    </div>

    <div class="editor-section">
      <div class="editor-section-header">
        <div class="editor-section-title">
          <i class="fas fa-list-ol"></i> Questions (<span id="quizHeaderCount">${quizDraft.length}</span>)
          <span style="font-size:12px;color:var(--text-tertiary);font-weight:500;margin-left:8px;">
            Total marks: <span id="quizHeaderMarks">${autoTotal}</span>
          </span>
        </div>
        <div style="display:flex;gap:8px;flex-wrap:wrap;">
          <button class="btn btn-outline btn-sm" onclick="addQuizQuestion('single')"><i class="fas fa-plus"></i> Single Correct</button>
          <button class="btn btn-outline btn-sm" onclick="addQuizQuestion('multiple')"><i class="fas fa-plus"></i> Multiple Correct</button>
          <button class="btn btn-outline btn-sm" onclick="addQuizQuestion('integer')"><i class="fas fa-plus"></i> Integer</button>
          <button class="btn btn-outline btn-sm" onclick="addQuizQuestion('numerical')"><i class="fas fa-plus"></i> Numerical Range</button>
          <button class="btn btn-outline btn-sm" onclick="addQuizQuestion('matrix')"><i class="fas fa-plus"></i> Matrix Match</button>
          <button class="btn btn-outline btn-sm" onclick="addQuizQuestion('subjective')"><i class="fas fa-plus"></i> Subjective</button>
        </div>
      </div>

      <p class="editor-hint">
        <strong>Overleaf-standard LaTeX is supported.</strong>
        Inline math: <code>$E = mc^2$</code> · Display math: <code>$$\\int_0^1 x^2\\,dx$$</code> ·
        Also supports <code>\\begin{align}</code>, <code>\\begin{pmatrix}</code>, <code>\\ce{H2O}</code>, <code>\\textcolor</code>, and all amsmath/physics macros.
        Live preview appears below every input.
      </p>

      <div id="quizDraftList"></div>

      <button class="btn btn-primary" style="width:100%;justify-content:center;margin-top:16px;"
              onclick="addQuizQuestion('single')">
        <i class="fas fa-plus"></i> Add Question
      </button>
    </div>
  `;

  renderQuizDraft();
  renderMathIn(container);
  startQuizAutosave();
}

function renderQuizDraft() {
  const list = document.getElementById('quizDraftList');
  if (!list) return;

  if (quizDraft.length === 0) {
    list.innerHTML = `<div class="empty-state"><i class="fas fa-question-circle"></i><p>No questions yet. Add your first question below.</p></div>`;
    updateQuizTotals();
    return;
  }

  let html = '';
  quizDraft.forEach((q, qi) => {
    html += `<div class="quiz-edit-card" data-qid="${qi}">
      <div class="quiz-edit-head">
        <div style="display:flex;align-items:center;gap:10px;flex-wrap:wrap;">
          <strong>Question ${qi + 1}</strong>
          <span class="mat-type">${questionTypeLabel(q.type)}</span>
          <span class="quiz-question-marks-badge">+${q.marks} / ${q.negativeMarks}</span>
        </div>
        <div class="quiz-question-controls">
          <button type="button" class="quiz-icon-btn" onclick="moveQuizQuestion(${qi}, -1)" title="Move up" ${qi === 0 ? 'disabled' : ''}>
            <i class="fas fa-arrow-up"></i>
          </button>
          <button type="button" class="quiz-icon-btn" onclick="moveQuizQuestion(${qi}, 1)" title="Move down" ${qi === quizDraft.length - 1 ? 'disabled' : ''}>
            <i class="fas fa-arrow-down"></i>
          </button>
          <button type="button" class="quiz-icon-btn" onclick="duplicateQuizQuestion(${qi})" title="Duplicate">
            <i class="fas fa-copy"></i>
          </button>
          <button type="button" class="quiz-icon-btn danger" onclick="removeQuizQuestion(${qi})" title="Delete">
            <i class="fas fa-trash-alt"></i>
          </button>
        </div>
      </div>

      <div class="editor-grid-3" style="margin-bottom:12px;">
        <div class="form-group">
          <label>Question Type</label>
          <select onchange="updateQuizType(${qi}, this.value)">
            <option value="single"     ${q.type === 'single'     ? 'selected' : ''}>Single Correct (MCQ)</option>
            <option value="multiple"   ${q.type === 'multiple'   ? 'selected' : ''}>Multiple Correct (MSQ)</option>
            <option value="integer"    ${q.type === 'integer'    ? 'selected' : ''}>Integer (exact match)</option>
            <option value="numerical"  ${q.type === 'numerical'  ? 'selected' : ''}>⭐ Numerical Range (min–max)</option>
            <option value="matrix"     ${q.type === 'matrix'     ? 'selected' : ''}>Matrix Match</option>
            <option value="subjective" ${q.type === 'subjective' ? 'selected' : ''}>⭐ Subjective (admin evaluates)</option>
          </select>
        </div>
        <div class="form-group">
          <label>Marks (+)</label>
          <input type="number" value="${q.marks}" min="0" step="0.5"
                 oninput="updateQuizField(${qi}, 'marks', parseFloat(this.value) || 0)">
        </div>
        <div class="form-group">
          <label>Negative Marks (−)</label>
          <input type="number" value="${q.negativeMarks}" step="0.5"
                 oninput="updateQuizField(${qi}, 'negativeMarks', parseFloat(this.value) || 0)">
        </div>
      </div>

      <div class="form-group" style="margin-bottom:14px;">
        <label>Question Text <span class="hint" style="display:inline;">· LaTeX supported</span></label>
        <textarea rows="3" class="latex-source" data-preview-id="q${qi}-question"
                  placeholder="e.g. Find $\\int_0^1 x^2 \\, dx$"
                  oninput="updateQuizField(${qi}, 'question', this.value)">${escapeHtml(q.question)}</textarea>
        ${latexPreviewBox(`q${qi}-question`, q.question)}
      </div>

      ${renderAnswerArea(q, qi)}

      <div class="form-group" style="margin-top:12px;">
        <label>Explanation / Solution (optional · LaTeX supported)</label>
        <textarea rows="2" class="latex-source" data-preview-id="q${qi}-explanation"
                  placeholder="e.g. Using power rule: $\\frac{x^3}{3}\\Big|_0^1 = \\frac{1}{3}$"
                  oninput="updateQuizField(${qi}, 'explanation', this.value)">${escapeHtml(q.explanation || '')}</textarea>
        ${latexPreviewBox(`q${qi}-explanation`, q.explanation || '')}
      </div>
    </div>`;
  });

  list.innerHTML = html;
  renderMathIn(list);
  updateQuizTotals();
}

function questionTypeLabel(t) {
  return ({
    single: 'SINGLE',
    multiple: 'MULTIPLE',
    integer: 'INTEGER',
    numerical: 'NUMERICAL RANGE',
    matrix: 'MATRIX',
    subjective: 'SUBJECTIVE'
  })[t] || 'SINGLE';
}

function renderAnswerArea(q, qi) {
  if (q.type === 'single' || q.type === 'multiple') {
    const inputType = q.type === 'single' ? 'radio' : 'checkbox';
    const inputName = `q-${qi}-${q.type}`;

    return `
      <div class="quiz-options-block">
        <label style="font-size:12.5px;font-weight:600;color:var(--text-secondary);display:block;margin-bottom:8px;">
          Options ${q.type === 'multiple' ? '(check ALL correct)' : '(select ONE correct)'}
        </label>
        ${(q.options || []).map((opt, oi) => {
          const checked = (q.correctIndexes || []).includes(oi);
          return `
            <div class="quiz-option-row">
              <label class="quiz-radio">
                <input type="${inputType}" name="${inputName}"
                       ${checked ? 'checked' : ''}
                       onchange="updateQuizCorrect(${qi}, ${oi}, this.checked, '${q.type}')">
                <span class="quiz-radio-dot"></span>
              </label>
              <div class="quiz-option-input-wrap">
                <input type="text" class="latex-source" data-preview-id="q${qi}-opt${oi}"
                       placeholder="Option ${String.fromCharCode(65 + oi)} · LaTeX ok"
                       value="${escapeHtml(opt)}"
                       oninput="updateQuizOption(${qi}, ${oi}, this.value)">
                ${latexPreviewBox(`q${qi}-opt${oi}`, opt)}
              </div>
              <button type="button" class="quiz-remove" style="width:24px;height:24px;"
                      onclick="removeQuizOption(${qi}, ${oi})" title="Remove option">
                <i class="fas fa-times" style="font-size:10px;"></i>
              </button>
            </div>`;
        }).join('')}
        <button type="button" class="btn btn-outline btn-sm" style="margin-top:8px;"
                onclick="addQuizOption(${qi})">
          <i class="fas fa-plus"></i> Add Option
        </button>
      </div>`;
  }

  if (q.type === 'integer') {
    return `
      <div class="editor-grid-2">
        <div class="form-group">
          <label>Correct Integer / Numeric Answer</label>
          <input type="number" step="any"
                 value="${q.integerAnswer === null ? '' : q.integerAnswer}"
                 placeholder="e.g. 42"
                 oninput="updateQuizField(${qi}, 'integerAnswer', this.value === '' ? null : parseFloat(this.value))">
        </div>
        <div class="form-group">
          <label>Tolerance (±)</label>
          <input type="number" step="any" min="0"
                 value="${q.integerTolerance || 0}"
                 placeholder="0 = exact match"
                 oninput="updateQuizField(${qi}, 'integerTolerance', parseFloat(this.value) || 0)">
          <span class="hint">If set to 0.5, answers within ±0.5 are accepted.</span>
        </div>
      </div>`;
  }

  if (q.type === 'matrix') {
    const leftItems  = q.matrixLeftItems  || [];
    const rightItems = q.matrixRightItems || [];
    const rows       = q.matrixRows       || [];

    return `
      <div class="matrix-match-block">
        <div class="editor-grid-2">
          <div>
            <label style="font-size:12.5px;font-weight:600;color:var(--text-secondary);display:block;margin-bottom:8px;">
              List-I (Left Column · items to be matched)
            </label>
            ${leftItems.map((item, li) => `
              <div class="quiz-option-row" style="margin-bottom:10px;">
                <span class="quiz-play-letter">${String.fromCharCode(65 + li)}</span>
                <div class="quiz-option-input-wrap">
                  <input type="text" class="latex-source" data-preview-id="q${qi}-L${li}"
                         placeholder="Item ${String.fromCharCode(65 + li)} · LaTeX ok"
                         value="${escapeHtml(item)}"
                         oninput="updateMatrixItem(${qi}, 'left', ${li}, this.value)">
                  ${latexPreviewBox(`q${qi}-L${li}`, item)}
                </div>
                <button type="button" class="quiz-remove" style="width:24px;height:24px;"
                        onclick="removeMatrixItem(${qi}, 'left', ${li})" title="Remove">
                  <i class="fas fa-times" style="font-size:10px;"></i>
                </button>
              </div>`).join('')}
            <button type="button" class="btn btn-outline btn-sm" onclick="addMatrixItem(${qi}, 'left')">
              <i class="fas fa-plus"></i> Add Left Item
            </button>
          </div>
          <div>
            <label style="font-size:12.5px;font-weight:600;color:var(--text-secondary);display:block;margin-bottom:8px;">
              List-II (Right Column · items to match to)
            </label>
            ${rightItems.map((item, ri) => `
              <div class="quiz-option-row" style="margin-bottom:10px;">
                <span class="quiz-play-letter">${['P','Q','R','S','T','U','V','W'][ri] || (ri + 1)}</span>
                <div class="quiz-option-input-wrap">
                  <input type="text" class="latex-source" data-preview-id="q${qi}-R${ri}"
                         placeholder="Item ${['P','Q','R','S','T','U','V','W'][ri] || (ri + 1)} · LaTeX ok"
                         value="${escapeHtml(item)}"
                         oninput="updateMatrixItem(${qi}, 'right', ${ri}, this.value)">
                  ${latexPreviewBox(`q${qi}-R${ri}`, item)}
                </div>
                <button type="button" class="quiz-remove" style="width:24px;height:24px;"
                        onclick="removeMatrixItem(${qi}, 'right', ${ri})" title="Remove">
                  <i class="fas fa-times" style="font-size:10px;"></i>
                </button>
              </div>`).join('')}
            <button type="button" class="btn btn-outline btn-sm" onclick="addMatrixItem(${qi}, 'right')">
              <i class="fas fa-plus"></i> Add Right Item
            </button>
          </div>
        </div>

        <div style="margin-top:16px;">
          <label style="font-size:12.5px;font-weight:600;color:var(--text-secondary);display:block;margin-bottom:8px;">
            Correct Matching (for each List-I item, choose the List-II match)
          </label>
          ${rows.map((r, ri) => `
            <div class="quiz-option-row" style="margin-bottom:8px;">
              <span class="quiz-play-letter">${String.fromCharCode(65 + ri)}</span>
              <input type="text" style="flex:1;" class="latex-source" data-preview-id="q${qi}-row${ri}"
                     placeholder="Row ${String.fromCharCode(65 + ri)} text (LaTeX ok)"
                     value="${escapeHtml(r.text)}"
                     oninput="updateMatrixRow(${qi}, ${ri}, 'text', this.value)">
              <span style="font-size:12px;color:var(--text-tertiary);padding:0 8px;">→</span>
              <select style="min-width:120px;" onchange="updateMatrixRow(${qi}, ${ri}, 'correctIndex', parseInt(this.value,10) || 0)">
                ${(rightItems.length ? rightItems : ['P','Q','R','S']).map((_, x) => {
                  const label = ['P','Q','R','S','T','U','V','W'][x] || (x + 1);
                  return `<option value="${x}" ${Number(r.correctIndex) === x ? 'selected' : ''}>${label}</option>`;
                }).join('')}
              </select>
              <button type="button" class="quiz-remove" style="width:24px;height:24px;"
                      onclick="removeMatrixRow(${qi}, ${ri})" title="Remove row">
                <i class="fas fa-times" style="font-size:10px;"></i>
              </button>
            </div>
          `).join('')}
          <button type="button" class="btn btn-outline btn-sm" onclick="addMatrixRow(${qi})">
            <i class="fas fa-plus"></i> Add Row
          </button>
        </div>
      </div>`;
  }
    if (q.type === 'numerical') {
    return `
      <div class="editor-grid-2">
        <div class="form-group">
          <label><i class="fas fa-arrow-down"></i> Minimum Accepted Value</label>
          <input type="number" step="any"
                 value="${q.rangeMin === null || q.rangeMin === undefined ? '' : q.rangeMin}"
                 placeholder="e.g. 9.7"
                 oninput="updateQuizField(${qi}, 'rangeMin', this.value === '' ? null : parseFloat(this.value))">
        </div>
        <div class="form-group">
          <label><i class="fas fa-arrow-up"></i> Maximum Accepted Value</label>
          <input type="number" step="any"
                 value="${q.rangeMax === null || q.rangeMax === undefined ? '' : q.rangeMax}"
                 placeholder="e.g. 10.3"
                 oninput="updateQuizField(${qi}, 'rangeMax', this.value === '' ? null : parseFloat(this.value))">
        </div>
      </div>
      <div class="numerical-range-preview">
        <i class="fas fa-bullseye"></i>
        <span>
          Any answer between
          <strong>${q.rangeMin ?? '?'}</strong> and <strong>${q.rangeMax ?? '?'}</strong>
          (inclusive) will be marked as <span class="ok-text">CORRECT</span>.
        </span>
      </div>`;
  }

  if (q.type === 'subjective') {
    return `
      <div class="editor-grid-2">
        <div class="form-group">
          <label><i class="fas fa-star"></i> Maximum Marks</label>
          <input type="number" min="1" max="1000" step="0.5"
                 value="${q.subjectiveMaxMarks || 10}"
                 oninput="updateQuizField(${qi}, 'subjectiveMaxMarks', parseFloat(this.value) || 10); updateQuizField(${qi}, 'marks', parseFloat(this.value) || 10);">
          <span class="hint">Admin can award marks from 0 up to this maximum.</span>
        </div>
        <div class="form-group">
          <label><i class="fas fa-info-circle"></i> Instructions for Students (optional)</label>
          <textarea rows="2" maxlength="500"
                    placeholder="e.g. Show all steps clearly. Upload clear, well-lit photos of your handwritten solution."
                    oninput="updateQuizField(${qi}, 'subjectiveInstructions', this.value)">${escapeHtml(q.subjectiveInstructions || '')}</textarea>
        </div>
      </div>
      <div class="subjective-info-box">
        <i class="fas fa-camera"></i>
        <div>
          <strong>How this works:</strong>
          <ul>
            <li>Students upload <strong>photos of their handwritten solution</strong> (JPG / PNG).</li>
            <li>Subjective answers are <strong>not auto-graded</strong> — they are marked as <em>Pending Evaluation</em>.</li>
            <li>Admin reviews submissions in the admin panel and awards marks out of <strong>${q.subjectiveMaxMarks || 10}</strong>.</li>
          </ul>
        </div>
      </div>`;
  }

  return '';
}


/* ============================================================
   QUIZ EDITOR — Question mutators
   ============================================================ */
function addQuizQuestion(type = 'single') {
  const base = {
    type,
    question: '',
    explanation: '',
    marks: 4,
    negativeMarks: -1
  };
  if (type === 'single' || type === 'multiple') {
    base.options = ['', '', '', ''];
    base.correctIndexes = [];
  } else if (type === 'integer') {
    base.integerAnswer = null;
    base.integerTolerance = 0;
  } else if (type === 'numerical') {          // ⭐ NEW
    base.rangeMin = null;
    base.rangeMax = null;
    base.negativeMarks = 0;                   // no negative for range typically
  } else if (type === 'matrix') {
    base.matrixLeftItems  = ['', '', '', ''];
    base.matrixRightItems = ['', '', '', ''];
    base.matrixRows = [0, 1, 2, 3].map(i => ({ text: '', correctIndex: i }));
  } else if (type === 'subjective') {         // ⭐ NEW
    base.subjectiveMaxMarks = 10;
    base.subjectiveInstructions = '';
    base.marks = 10;                          // mirror subjectiveMaxMarks
    base.negativeMarks = 0;                   // no negative for subjective
  }
  quizDraft.push(base);
  renderQuizDraft();
}

function removeQuizQuestion(qi) {
  if (!confirm(`Delete Question ${qi + 1}?`)) return;
  quizDraft.splice(qi, 1);
  renderQuizDraft();
}

function duplicateQuizQuestion(qi) {
  const clone = JSON.parse(JSON.stringify(quizDraft[qi]));
  quizDraft.splice(qi + 1, 0, clone);
  renderQuizDraft();
  showToast(`Question ${qi + 1} duplicated.`, 'success');
}

function moveQuizQuestion(qi, delta) {
  const target = qi + delta;
  if (target < 0 || target >= quizDraft.length) return;
  const [item] = quizDraft.splice(qi, 1);
  quizDraft.splice(target, 0, item);
  renderQuizDraft();
}

function updateQuizType(qi, newType) {
  const q = quizDraft[qi];
  if (!q) return;
  const oldType = q.type;
  q.type = newType;

  // Cleanup fields that don't belong to the new type
  const resetCommon = () => {
    q.options = [];
    q.correctIndexes = [];
    q.matrixLeftItems = [];
    q.matrixRightItems = [];
    q.matrixRows = [];
    q.integerAnswer = null;
    q.integerTolerance = 0;
    q.rangeMin = null;
    q.rangeMax = null;
    q.subjectiveMaxMarks = q.subjectiveMaxMarks || 10;
    q.subjectiveInstructions = q.subjectiveInstructions || '';
  };

  if (newType === 'integer' && oldType !== 'integer') {
    resetCommon();
  } else if (newType === 'numerical' && oldType !== 'numerical') {   // ⭐ NEW
    resetCommon();
    q.negativeMarks = 0;
  } else if (newType === 'matrix' && oldType !== 'matrix') {
    resetCommon();
    q.matrixLeftItems  = ['', '', '', ''];
    q.matrixRightItems = ['', '', '', ''];
    q.matrixRows = [0, 1, 2, 3].map(i => ({ text: '', correctIndex: i }));
  } else if (newType === 'subjective' && oldType !== 'subjective') { // ⭐ NEW
    resetCommon();
    if (!q.subjectiveMaxMarks || q.subjectiveMaxMarks < 1) q.subjectiveMaxMarks = 10;
    q.marks = q.subjectiveMaxMarks;
    q.negativeMarks = 0;
  } else if ((newType === 'single' || newType === 'multiple') &&
             oldType !== 'single' && oldType !== 'multiple') {
    resetCommon();
    if (!q.options || q.options.length === 0) q.options = ['', '', '', ''];
    if (!Array.isArray(q.correctIndexes)) q.correctIndexes = [];
  }

  if (newType === 'single' && Array.isArray(q.correctIndexes) && q.correctIndexes.length > 1) {
    q.correctIndexes = [q.correctIndexes[0]];
  }

  renderQuizDraft();
}

function updateQuizField(qi, field, value) {
  if (quizDraft[qi]) quizDraft[qi][field] = value;
  if (field === 'marks' || field === 'negativeMarks') updateQuizTotals();
}

function updateQuizOption(qi, oi, value) {
  if (quizDraft[qi] && quizDraft[qi].options) quizDraft[qi].options[oi] = value;
}

function addQuizOption(qi) {
  const q = quizDraft[qi];
  if (!q || !q.options) return;
  if (q.options.length >= 8) return showToast('Max 8 options.', 'info');
  q.options.push('');
  renderQuizDraft();
}

function removeQuizOption(qi, oi) {
  const q = quizDraft[qi];
  if (!q || !q.options) return;
  if (q.options.length <= 2) return showToast('At least 2 options required.', 'info');
  q.options.splice(oi, 1);
  q.correctIndexes = (q.correctIndexes || [])
    .filter(x => x !== oi)
    .map(x => x > oi ? x - 1 : x);
  renderQuizDraft();
}

function updateQuizCorrect(qi, oi, isChecked, type) {
  const q = quizDraft[qi];
  if (!q) return;
  if (!Array.isArray(q.correctIndexes)) q.correctIndexes = [];
  if (type === 'single') {
    q.correctIndexes = [oi];
  } else {
    if (isChecked) {
      if (!q.correctIndexes.includes(oi)) q.correctIndexes.push(oi);
    } else {
      q.correctIndexes = q.correctIndexes.filter(x => x !== oi);
    }
  }
}

function updateMatrixItem(qi, side, idx, value) {
  const q = quizDraft[qi];
  if (!q) return;
  const key = side === 'left' ? 'matrixLeftItems' : 'matrixRightItems';
  if (!Array.isArray(q[key])) q[key] = [];
  q[key][idx] = value;
}

function addMatrixItem(qi, side) {
  const q = quizDraft[qi];
  if (!q) return;
  const key = side === 'left' ? 'matrixLeftItems' : 'matrixRightItems';
  if (!Array.isArray(q[key])) q[key] = [];
  if (q[key].length >= 8) return showToast('Max 8 items per column.', 'info');
  q[key].push('');
  if (side === 'left') {
    if (!Array.isArray(q.matrixRows)) q.matrixRows = [];
    q.matrixRows.push({ text: '', correctIndex: 0 });
  }
  renderQuizDraft();
}

function removeMatrixItem(qi, side, idx) {
  const q = quizDraft[qi];
  if (!q) return;
  const key = side === 'left' ? 'matrixLeftItems' : 'matrixRightItems';
  if (!Array.isArray(q[key]) || q[key].length <= 2) {
    return showToast('At least 2 items required per column.', 'info');
  }
  q[key].splice(idx, 1);
  if (side === 'left' && Array.isArray(q.matrixRows)) q.matrixRows.splice(idx, 1);
  if (side === 'right' && Array.isArray(q.matrixRows)) {
    q.matrixRows.forEach(r => {
      if (Number(r.correctIndex) >= q.matrixRightItems.length) {
        r.correctIndex = q.matrixRightItems.length - 1;
      }
    });
  }
  renderQuizDraft();
}

function updateMatrixRow(qi, ri, field, value) {
  const q = quizDraft[qi];
  if (!q || !Array.isArray(q.matrixRows) || !q.matrixRows[ri]) return;
  q.matrixRows[ri][field] = value;
}

function addMatrixRow(qi) {
  const q = quizDraft[qi];
  if (!q) return;
  if (!Array.isArray(q.matrixRows)) q.matrixRows = [];
  if (q.matrixRows.length >= 8) return showToast('Max 8 rows.', 'info');
  q.matrixRows.push({ text: '', correctIndex: 0 });
  renderQuizDraft();
}

function removeMatrixRow(qi, ri) {
  const q = quizDraft[qi];
  if (!q || !Array.isArray(q.matrixRows)) return;
  if (q.matrixRows.length <= 2) return showToast('At least 2 rows required.', 'info');
  q.matrixRows.splice(ri, 1);
  renderQuizDraft();
}
/* ---- Visual feedback when the admin switches the nav policy ---- */
function onQuizNavPolicyChange() {
  const strict = document.querySelector('input[name="qpNavPolicy"][value="strict"]');
  const flex   = document.querySelector('input[name="qpNavPolicy"][value="flexible"]');
  const strictLbl = document.getElementById('qpNavStrictLabel');
  const flexLbl   = document.getElementById('qpNavFlexLabel');
  if (strictLbl) strictLbl.classList.toggle('active', !!(strict && strict.checked));
  if (flexLbl)   flexLbl.classList.toggle('active',   !!(flex   && flex.checked));
}

/* ============================================================
   QUIZ EDITOR — Save / Validate
   ============================================================ */
async function saveQuizPaper() {
  if (!quizEditingCourseId || !quizEditingMaterialId) return;

  const navPolicy = document.querySelector('input[name="qpNavPolicy"]:checked');
  const allowBack = navPolicy ? navPolicy.value === 'flexible' : false;
  const showPal   = $('qpShowPalette') ? $('qpShowPalette').checked : true;

  /* ⭐ Read the two new sections */
  const maxAttemptsRaw = parseInt($('qpMaxAttempts')?.value, 10);
  const maxAttempts    = Number.isFinite(maxAttemptsRaw)
    ? Math.max(0, Math.min(99, maxAttemptsRaw))
    : 0;

  const resultMode = $('qpResultMode')?.value || 'immediate';

  /* Absolute publish time — only meaningful in "scheduled" mode */
  let resultPublishAt = null;
  if (resultMode === 'scheduled') {
    const raw = $('qpPublishAt')?.value;          // "YYYY-MM-DDTHH:MM"
    if (raw) {
      const d = new Date(raw);
      if (!isNaN(d.getTime())) resultPublishAt = d.toISOString();
    }
  }

  /* Per-student delay — only meaningful in "scheduled" mode */
  let resultPublishDelayHours = 0;
  if (resultMode === 'scheduled') {
    const h = parseInt($('qpPublishDelayHours')?.value, 10);
    resultPublishDelayHours = Number.isFinite(h)
      ? Math.max(0, Math.min(8760, h))
      : 0;
  }

  quizPaperConfig = {
    subject:    ($('qpSubject')?.value || '').trim(),
    paperCode:  ($('qpCode')?.value    || '').trim(),
    totalTime:  ($('qpTime')?.value    || '').trim(),
    totalMarks: parseInt($('qpMarks')?.value, 10) || 0,

    /* Per-quiz navigation policy (unchanged) */
    allowBackNavigation: allowBack,
    showQuestionPalette: showPal,

    /* ⭐ NEW — Attempt limit + result publication */
    maxAttempts,
    resultPublishMode:       resultMode,
    resultPublishAt,
    resultPublishDelayHours
  };

  /* ---------- Per-question validation (unchanged) ---------- */
  for (let i = 0; i < quizDraft.length; i++) {
    const q = quizDraft[i];
    if (!q.question || !q.question.trim()) {
      return showToast(`Question ${i + 1} has no text.`, 'error');
    }
    if (q.type === 'single' || q.type === 'multiple') {
      const filled = (q.options || []).filter(o => o && o.trim());
      if (filled.length < 2) return showToast(`Question ${i + 1} needs at least 2 filled options.`, 'error');
      if (!Array.isArray(q.correctIndexes) || q.correctIndexes.length === 0) {
        return showToast(`Question ${i + 1} has no correct answer selected.`, 'error');
      }
      if (q.correctIndexes.some(x => !q.options[x] || !q.options[x].trim())) {
        return showToast(`Question ${i + 1}: a chosen correct option is empty.`, 'error');
      }
      if (q.type === 'single' && q.correctIndexes.length !== 1) {
        return showToast(`Question ${i + 1}: single correct must have exactly ONE correct option.`, 'error');
      }
    }
    if (q.type === 'integer') {
      if (q.integerAnswer === null || q.integerAnswer === undefined || isNaN(q.integerAnswer)) {
        return showToast(`Question ${i + 1}: integer answer required.`, 'error');
      }
    }
    if (q.type === 'numerical') {
      if (q.rangeMin === null || q.rangeMin === undefined || isNaN(Number(q.rangeMin))) {
        return showToast(`Question ${i + 1}: minimum value required.`, 'error');
      }
      if (q.rangeMax === null || q.rangeMax === undefined || isNaN(Number(q.rangeMax))) {
        return showToast(`Question ${i + 1}: maximum value required.`, 'error');
      }
      if (Number(q.rangeMin) > Number(q.rangeMax)) {
        return showToast(`Question ${i + 1}: minimum cannot exceed maximum.`, 'error');
      }
    }
    if (q.type === 'subjective') {
      const maxM = Number(q.subjectiveMaxMarks);
      if (!Number.isFinite(maxM) || maxM < 1) {
        return showToast(`Question ${i + 1}: maximum marks must be at least 1.`, 'error');
      }
    }
    if (q.type === 'matrix') {
      const left  = (q.matrixLeftItems  || []).filter(x => x && x.trim());
      const right = (q.matrixRightItems || []).filter(x => x && x.trim());
      if (left.length  < 2) return showToast(`Question ${i + 1}: at least 2 List-I items required.`, 'error');
      if (right.length < 2) return showToast(`Question ${i + 1}: at least 2 List-II items required.`, 'error');
      if ((q.matrixRows || []).length < 2) return showToast(`Question ${i + 1}: at least 2 rows required.`, 'error');
    }
  }

  const btn = $('quizSaveBtn');
  if (btn) { btn.disabled = true; btn.innerHTML = '<i class="fas fa-spinner fa-spin"></i> Saving…'; }

  if (!quizPaperConfig.totalMarks) {
    quizPaperConfig.totalMarks = quizDraft.reduce((s, q) => s + (Number(q.marks) || 0), 0);
  }

  try {
    const res = await fetch(
      `/api/courses/${quizEditingCourseId}/materials/${quizEditingMaterialId}/quiz`,
      {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ quiz: quizDraft, examConfig: quizPaperConfig })
      }
    );
    const data = await res.json();
    if (data.success) {
      showToast('✅ Paper saved!', 'success');
      await fetchCoursesFromDB();
    } else {
      showToast(data.message || 'Failed to save.', 'error');
    }
  } catch (e) {
    console.error(e);
    showToast('Server error while saving.', 'error');
  } finally {
    if (btn) { btn.disabled = false; btn.innerHTML = '<i class="fas fa-save"></i> Save Paper'; }
  }
}
/* ============================================================
   QUIZ — PROCTORED FULL-PAGE EXAM MODE
   ------------------------------------------------------------
   Config:
     QUIZ_PROCTOR_MAX_STRIKES
       0 = zero-tolerance → first violation auto-submits
       1 = one grace warning, second violation auto-submits  (default)
       2 = two grace warnings, third auto-submits
   ============================================================ */
/* Default strike limit — overridden at openQuizPlayer() time by the
   value in Settings (admin can configure 1–10). */
let QUIZ_PROCTOR_MAX_STRIKES = 3;

let quizPlayerState = null;

/* ⭐ FORWARD-ONLY + SERVER-TIMER + ANALYTICS state */
let _examSessionPoll = null;          // heartbeat interval handle
let _examClockOffsetMs = 0;           // serverNow - clientNow, applied to timer math
let _examQuestionEnteredAt = 0;       // ms — when the current question was first shown
let _examQuestionLocked = {};         // { [originalIdx]: true } once "Next" clicked

/* ---- Listener registry (cleanup after exam) ---- */
const _quizListeners = [];
function _attachProctorListener(target, event, handler, opts) {
  target.addEventListener(event, handler, opts);
  _quizListeners.push({ target, event, handler, opts });
}
function _detachAllProctorListeners() {
  while (_quizListeners.length) {
    const { target, event, handler, opts } = _quizListeners.pop();
    try { target.removeEventListener(event, handler, opts); } catch (e) {}
  }
}

/* ============================================================
   OPEN — Shows pre-exam consent first
   ============================================================ */
async function openQuizPlayer(courseId, materialId) {
  const course = findCourse(courseId); if (!course) return;
  const mat = (course.materials || []).find(m => m.id === materialId); if (!mat) return;

  // Quiz data is not in the cached list — fetch it on demand
  let quiz = mat.quiz;
  if (!quiz || quiz.length === 0) {
    try {
      showToast('Loading quiz…', 'info');
      const res = await fetch(`/api/courses/${courseId}/materials/${materialId}/full-quiz`);
      const data = await res.json();
      if (!data.success) return showToast(data.message || 'Could not load quiz.', 'error');
      quiz = data.quiz || [];
      mat.quiz = quiz;
      mat.examConfig = data.examConfig || mat.examConfig || {};
    } catch (e) {
      return showToast('Network error loading quiz.', 'error');
    }
  }
  if (quiz.length === 0) return showToast('This test has no questions yet.', 'info');

  /* ⭐ START the server-side session.
     The server enforces the deadline and returns the shuffle that
     must be applied to questions and options. If the server is
     unreachable we fall back to a local shuffle so the exam still
     runs — the client is not the enforcer anyway. */
  let sessionInfo = null;
  try {
    const sres = await fetchJSON(
      `/api/user/quiz/${courseId}/${materialId}/start`,
      {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ userId: currentUser._id })
      }
    );
    if (sres && sres.success) {
      sessionInfo = sres;
      _examClockOffsetMs = (Number(sres.serverNow) || Date.now()) - Date.now();
    } else if (sres && sres.code === 'ALREADY_SUBMITTED') {
      return showToast('You have already submitted this test. Use Retake to start again.', 'info');
    } else if (sres && sres.code === 'ATTEMPT_LIMIT_REACHED') {
      /* ⭐ Student has used every attempt the admin allowed.
         Show them their own result status instead of a wall. */
      const used      = Number(sres.attemptsUsed)  || 0;
      const cap       = Number(sres.maxAttempts)   || 0;
      const visible   = sres.resultsVisible === true;
      const pending   = sres.resultsPending === true;

      if (visible) {
        return showToast(
          `You have used all ${cap} attempt${cap === 1 ? '' : 's'} for this test. ` +
          `Open the course to see your result.`,
          'info'
        );
      }
      if (pending) {
        return showToast(
          `You have used all ${cap} attempt${cap === 1 ? '' : 's'}. ` +
          `Your result will be visible once the instructor publishes it.`,
          'info'
        );
      }
      return showToast(
        `Attempt limit reached (${used}/${cap}).`,
        'error'
      );
    }
  } catch (err) {
    console.warn('[openQuizPlayer] session start failed, running offline:', err.message);
  }

  const normalized = quiz.map(q => normalizeQuestion(q));
  const emptyAnswer = q => q.type === 'integer' || q.type === 'numerical' ? '' : [];

  const saved = restoreQuizAnswers(materialId);
  const initialAnswers = (saved && Array.isArray(saved) && saved.length === normalized.length)
    ? saved
    : normalized.map(emptyAnswer);

  /* Read the admin's proctoring config (defaults if fetch failed) */
  let cfg = { maxStrikes: 3, forwardOnly: true, shuffleQuestions: true, shuffleOptions: true };
  try {
    const cfgRes = await fetchJSON('/api/settings/subscription').catch(() => null);
    if (cfgRes && cfgRes.exam) {
      cfg.maxStrikes = Number(cfgRes.exam.maxStrikes) || cfg.maxStrikes;
      cfg.forwardOnly = cfgRes.exam.forwardOnly !== false;
      cfg.shuffleQuestions = cfgRes.exam.shuffleQuestions !== false;
      cfg.shuffleOptions = cfgRes.exam.shuffleOptions !== false;
    }
  } catch (_) {}
  QUIZ_PROCTOR_MAX_STRIKES = Math.max(1, Math.min(10, cfg.maxStrikes));

  /* ⭐ Per-quiz override wins over the global default.
     The server has already resolved this in /start; if the response
     is missing (offline / legacy), fall back to the global setting. */
  let allowBackNavigation = !cfg.forwardOnly;
  let showQuestionPalette = true;
  if (sessionInfo) {
    if (typeof sessionInfo.allowBackNavigation === 'boolean') {
      allowBackNavigation = sessionInfo.allowBackNavigation;
    }
    if (typeof sessionInfo.showQuestionPalette === 'boolean') {
      showQuestionPalette = sessionInfo.showQuestionPalette;
    }
  }

  /* Build the display order. If the server responded with one, use
     it verbatim — it's the canonical order for this attempt. */
  let questionOrder;
  if (sessionInfo && Array.isArray(sessionInfo.questionOrder) && sessionInfo.questionOrder.length === normalized.length) {
    questionOrder = sessionInfo.questionOrder.slice();
  } else {
    questionOrder = Array.from({ length: normalized.length }, (_, i) => i);
    if (cfg.shuffleQuestions) {
      for (let i = questionOrder.length - 1; i > 0; i--) {
        const j = Math.floor(Math.random() * (i + 1));
        [questionOrder[i], questionOrder[j]] = [questionOrder[j], questionOrder[i]];
      }
    }
  }

  let optionOrders = (sessionInfo && sessionInfo.optionOrders) || {};
  if (!sessionInfo && cfg.shuffleOptions) {
    optionOrders = {};
    normalized.forEach((q, i) => {
      const n = (q.options || []).length;
      if (n > 1 && (q.type === 'single' || q.type === 'multiple')) {
        const arr = Array.from({ length: n }, (_, k) => k);
        for (let k = arr.length - 1; k > 0; k--) {
          const j = Math.floor(Math.random() * (k + 1));
          [arr[k], arr[j]] = [arr[j], arr[k]];
        }
        optionOrders[i] = arr;
      }
    });
  }

  quizPlayerState = {
    courseId, materialId,
    materialTitle: mat.title,
    quiz: normalized,
    answers: initialAnswers,
    submitted: false,
    response: null,
    paperConfig: mat.examConfig || {},
    previewMode: false,
    examStarted: false,
    strikes: 0,
    violations: [],
    startTime: null,
    violationHandling: false,
    fullscreenArmed: false,

    /* ⭐ NEW fields */
    forwardOnly: !allowBackNavigation,          // strict when back-nav is OFF
    allowBackNavigation,                        // ⭐ keep both, they read better
    showQuestionPalette: showQuestionPalette !== false,
    questionOrder,
    optionOrders,
    displayIndex: 0,
    serverStartedAt: sessionInfo ? sessionInfo.startedAt : Date.now(),
    durationSeconds: sessionInfo ? Number(sessionInfo.durationSeconds) || 0 : parseQuizTime(mat.examConfig && mat.examConfig.totalTime),
    timeSpentPerQuestion: {},
    questionLocked: {}
  };

  /* Reset per-question timers */
  _examQuestionEnteredAt = 0;
  _examQuestionLocked = {};

  const cb = document.getElementById('preExamConsentBox');
  if (cb) cb.checked = false;
  const btn = document.getElementById('preExamBeginBtn');
  if (btn) btn.disabled = true;

  /* ⭐ Dynamically update the pre-exam rules to match this quiz's policy.
     Strict mode  → show the red "Forward-only" row, hide the "Flexible" row.
     Flexible mode → show the green "Flexible" row, hide the red one. */
  const warnBox    = document.getElementById('preExamForwardOnly');
  const flexBox    = document.getElementById('preExamFlexible');
  const isMultiQ   = normalized.length > 1;
  const isStrict   = quizPlayerState.forwardOnly && isMultiQ;
  const isFlexible = !quizPlayerState.forwardOnly && isMultiQ;

  if (warnBox) warnBox.style.display = isStrict   ? 'flex' : 'none';
  if (flexBox) flexBox.style.display = isFlexible ? 'flex' : 'none';

  /* Also swap the consent line so it matches */
  const consentText = document.getElementById('preExamConsentText');
  if (consentText) {
    consentText.innerHTML = isStrict
      ? 'I understand and agree. I cannot return to previous questions once I click <em>Next</em>, and any violation will consume a strike.'
      : 'I understand and agree. I may revisit earlier questions before final submission, and any violation will consume a strike.';
  }
  /* ============================================================
     ⭐ ROLE-BASED PREVIEW BYPASS
     ------------------------------------------------------------
     Admins and instructors should NEVER be subjected to the
     proctored consent screen, fullscreen lock, or tab-switch
     strikes. When an admin opens a quiz, we route them straight
     into PREVIEW mode: the exam shell renders with no proctoring
     listeners, no countdown enforcement, and a visible
     "Preview mode" note. Students proceed to the normal consent
     modal exactly as before.
     ============================================================ */
  if (isAdmin(currentUser)) {
    // Force preview semantics — this is the single source of truth
    // that renderQuizExamShell() and submitQuiz() already read.
    quizPlayerState.previewMode = true;
    quizPlayerState.examStarted = false;
    quizPlayerState.forwardOnly = false;      // free nav for the admin
    quizPlayerState.allowBackNavigation = true;
    quizPlayerState.showQuestionPalette = true;
    quizPlayerState.questionLocked = {};
    quizPlayerState.strikes = 0;

    // Tear down the consent gate (it may have been pre-populated)
    const cb  = document.getElementById('preExamConsentBox');
    const btn = document.getElementById('preExamBeginBtn');
    if (cb)  cb.checked = false;
    if (btn) btn.disabled = true;
    closeModal('preExamWarningModal');

    // Mount the exam shell directly — no modal, no fullscreen,
    // no proctoring listeners.
    const shell = document.getElementById('quizExamShell');
    if (shell) {
      shell.style.display = 'flex';
      shell.setAttribute('aria-hidden', 'false');
      document.body.style.overflow = 'hidden';
    }

    renderQuizExamShell();          // previewMode → "Close Preview" footer
    showToast('Preview mode — proctoring disabled.', 'info');
    return;                         // short-circuit the student path
  }

  openModal('preExamWarningModal');
}

function togglePreExamConsent() {
  const cb = document.getElementById('preExamConsentBox');
  const btn = document.getElementById('preExamBeginBtn');
  if (btn) btn.disabled = !(cb && cb.checked);
}

function cancelPreExam() {
  closeModal('preExamWarningModal');
  quizPlayerState = null;
}

/* ============================================================
   BEGIN — Fullscreen + proctoring listeners
   ============================================================ */
async function beginExamSession() {
  if (!quizPlayerState) return;
  closeModal('preExamWarningModal');

  const shell = document.getElementById('quizExamShell');
  if (!shell) return;
  shell.style.display = 'flex';
  shell.setAttribute('aria-hidden', 'false');
  document.body.style.overflow = 'hidden';

  try {
    const el = document.documentElement;
    const req = el.requestFullscreen || el.webkitRequestFullscreen || el.msRequestFullscreen;
    if (req) { const p = req.call(el); if (p && p.catch) p.catch(() => {}); }
  } catch (e) {}

  quizPlayerState.examStarted = true;
  quizPlayerState.startTime = Date.now();

  _attachProctorListener(document, 'visibilitychange', _onExamVisibilityChange);
  _attachProctorListener(window, 'blur', _onExamWindowBlur);
  _attachProctorListener(document, 'fullscreenchange', _onExamFullscreenChange);
  _attachProctorListener(document, 'webkitfullscreenchange', _onExamFullscreenChange);
  _attachProctorListener(window, 'beforeunload', _onExamBeforeUnload);

  _attachProctorListener(document, 'contextmenu', _blockContextMenu, true);
  _attachProctorListener(document, 'copy', _blockCopy, true);
  _attachProctorListener(document, 'cut', _blockCopy, true);
  _attachProctorListener(document, 'paste', _blockCopy, true);
  _attachProctorListener(document, 'selectstart', _blockSelectStart, true);
  _attachProctorListener(document, 'dragstart', _blockDrag, true);
  _attachProctorListener(document, 'keydown', _blockDevKeys, true);

  setTimeout(() => { if (quizPlayerState) quizPlayerState.fullscreenArmed = true; }, 900);

  /* ⭐ Mark entry time for question 1 */
  _examQuestionEnteredAt = Date.now();

  renderQuizExamShell();
  startQuizTimer();
  showToast('Exam started. Good luck!', 'success');
}
/* ============================================================
   QUESTION PALETTE — numbered navigator strip
   ------------------------------------------------------------
   Behaviour depends on the per-quiz policy:
     • Strict mode  → only the CURRENT question's cell is enabled.
                      All others are visually muted and disabled.
     • Flexible mode → every cell is clickable; the student can
                      jump to any question at any time.
   ============================================================ */
function _renderQuestionPalette(st) {
  if (!st || !st.showQuestionPalette) return '';
  const total = st.questionOrder.length;
  if (total < 2) return '';               // pointless for 1-question exams

  let cells = '';
  for (let displayIdx = 0; displayIdx < total; displayIdx++) {
    const originalIdx = st.questionOrder[displayIdx];
    const q = st.quiz[originalIdx];
    const a = st.answers[originalIdx];
    const isAnswered = _isQuestionAnswered(q, a);
    const isCurrent  = displayIdx === st.displayIndex;
    const isLocked   = st.forwardOnly && displayIdx !== st.displayIndex;

    const classes = ['quiz-palette-cell'];
    if (isCurrent)  classes.push('current');
    if (isAnswered) classes.push('answered');
    if (isLocked)   classes.push('locked');

    const title = isLocked
      ? 'Locked — this quiz is forward-only'
      : `Go to question ${displayIdx + 1}`;

    cells += `<button type="button"
                class="${classes.join(' ')}"
                data-display-index="${displayIdx}"
                ${isLocked ? 'disabled' : ''}
                title="${title}"
                onclick="jumpToExamQuestion(${displayIdx})">
                ${displayIdx + 1}
              </button>`;
  }

  return `
    <div class="quiz-palette" id="quizPalette">
      <div class="quiz-palette-head">
        <i class="fas fa-th"></i>
        <span class="quiz-palette-title">Question Navigator</span>
        <span class="quiz-palette-mode ${st.forwardOnly ? 'strict' : 'flexible'}">
          <i class="fas ${st.forwardOnly ? 'fa-lock' : 'fa-arrows-left-right'}"></i>
          ${st.forwardOnly ? 'Forward-only' : 'Free navigation'}
        </span>
        <span class="quiz-palette-count">
          ${st.displayIndex + 1} / ${total}
        </span>
      </div>
      <div class="quiz-palette-grid">${cells}</div>
    </div>`;
}

/* ---- Jump to a specific question (used by the palette) ---- */
function jumpToExamQuestion(displayIdx) {
  const st = quizPlayerState;
  if (!st || st.submitted) return;
  if (displayIdx < 0 || displayIdx >= st.questionOrder.length) return;

  /* Strict mode: only the current cell is allowed */
  if (st.forwardOnly && displayIdx !== st.displayIndex) {
    return showToast('This quiz is forward-only. Use “Next Question”.', 'info');
  }

  /* Record the time spent on the question we're leaving */
  const fromOrigIdx = st.questionOrder[st.displayIndex];
  _recordQuestionTime(fromOrigIdx);

  /* In flexible mode, lock nothing — the answer is still editable.
     In strict mode we never reach here for a different index. */

  st.displayIndex = displayIdx;
  _examQuestionEnteredAt = Date.now();

  renderQuizExamShell();
  const body = document.querySelector('.quiz-exam-body');
  if (body) body.scrollTop = 0;
}

/* ---- Previous question (flexible mode only) ---- */
function prevExamQuestion() {
  const st = quizPlayerState;
  if (!st || st.submitted) return;
  if (st.forwardOnly) return;
  if (st.displayIndex <= 0) return;
  jumpToExamQuestion(st.displayIndex - 1);
}
/* ============================================================
   RENDER — Full-page shell
   ============================================================ */
function renderQuizExamShell() {
  const st = quizPlayerState; if (!st) return;
  const shell = document.getElementById('quizExamShell');
  if (!shell) return;

  const cfg = st.paperConfig || {};
  const course = findCourse(st.courseId);
  const mat = course && (course.materials || []).find(m => m.id === st.materialId);
  const examCfg = cfg.subject ? cfg : (mat && mat.examConfig) || {};

  const totalQ = st.quiz.length;

  /* ---------- Answered count (across every question) ---------- */
  const answered = st.quiz.reduce((s, q, i) => {
    const a = st.answers[i];
    const t = q.type || 'single';
    if (t === 'integer' || t === 'numerical') {
      return s + (a !== '' && a !== null && a !== undefined && !isNaN(Number(a)) ? 1 : 0);
    }
    if (t === 'matrix') {
      const rows = q.matrixRows || [];
      const filled = Array.isArray(a) ? a.filter(x => x !== undefined && x !== null && x !== '').length : 0;
      return s + (filled >= rows.length ? 1 : 0);
    }
    if (t === 'subjective') {
      return s + (Array.isArray(a) && a.some(u => u && u.url) ? 1 : 0);
    }
    return s + (Array.isArray(a) ? (a.length > 0 ? 1 : 0) : (a >= 0 ? 1 : 0));
  }, 0);

  const headerHtml = `
    <header class="quiz-exam-header">
      <div class="quiz-exam-title-group">
        <div class="quiz-exam-title">
          <i class="fas fa-file-pen"></i>
          ${escapeHtml(examCfg.subject || st.materialTitle)}
        </div>
        <div class="quiz-exam-sub">
          ${examCfg.paperCode ? `<span><i class="fas fa-hashtag"></i> ${escapeHtml(examCfg.paperCode)}</span>` : ''}
          <span><i class="fas fa-list-ol"></i> ${totalQ} question${totalQ === 1 ? '' : 's'}</span>
          ${examCfg.totalMarks ? `<span><i class="fas fa-star"></i> Max ${examCfg.totalMarks}</span>` : ''}
        </div>
      </div>

      <div class="quiz-exam-timer-wrap">
        <div class="quiz-exam-timer" id="quizTimerDisplay">--:--</div>
        ${st.previewMode ? '' : '<div class="quiz-proctor-pill"><i class="fas fa-shield-halved"></i> Proctored</div>'}
      </div>

      <div class="quiz-exam-progress">
        <span class="quiz-exam-progress-text">
          <strong>${answered}</strong> / ${totalQ} answered
        </span>
        <div class="quiz-exam-progress-bar">
          <div class="quiz-exam-progress-fill"
               style="width:${totalQ > 0 ? (answered / totalQ) * 100 : 0}%"></div>
        </div>
      </div>
    </header>
  ` + _renderQuestionPalette(st);

  /* ============================================================
     BODY — depends on whether the exam has been submitted.
     ============================================================ */
  let bodyHtml = '';

  if (!st.submitted) {
    /* ⭐ FORWARD-ONLY: render exactly ONE question at a time. */
    const qHtml = st.forwardOnly
      ? _renderSingleExamQuestion(st)
      : _renderAllExamQuestions(st);
    bodyHtml = `<div class="quiz-exam-body-inner">${qHtml}</div>`;
  } else {
    /* ---------- SUBMITTED ---------- */
    const resp = st.response || {};
    const isPending = resp.pendingPublication === true;

    if (isPending) {
      /* ⭐ Score withheld — admin scheduled the publication (or set it to manual) */
      const pubAt = resp.resultPublishAt
        ? new Date(resp.resultPublishAt).toLocaleString('en-IN', {
            day: 'numeric', month: 'short', year: 'numeric',
            hour: '2-digit', minute: '2-digit'
          })
        : null;

      const subjCount = Number(resp.subjectiveCount) || 0;

      bodyHtml = `<div class="quiz-exam-body-inner">
        <div class="quiz-result-hero pass" style="background:linear-gradient(135deg,rgba(99,102,241,.14),rgba(6,182,212,.06));border-color:rgba(99,102,241,.35);">
          <div class="quiz-result-emoji">⏳</div>
          <div class="quiz-result-score" style="font-size:22px;">Results Pending</div>
          <div class="quiz-result-headline" style="max-width:520px;margin:12px auto 0;font-size:13.5px;line-height:1.6;">
            ${escapeHtml(resp.message || 'Your answers have been recorded.')}
          </div>
          ${pubAt ? `<div style="margin-top:14px;font-size:12.5px;color:var(--text-tertiary);">
            Scheduled publication: <strong>${escapeHtml(pubAt)}</strong>
          </div>` : ''}
          ${subjCount > 0 ? `<p style="margin-top:14px;font-size:12.5px;color:var(--text-tertiary);">
            Your submission includes <strong>${subjCount}</strong> manually-evaluated question${subjCount === 1 ? '' : 's'}.
          </p>` : ''}
        </div>
        <p style="text-align:center;font-size:12.5px;color:var(--text-tertiary);margin-top:14px;">
          You'll be notified by email and in your dashboard the moment the results go live.
        </p>
      </div>`;
    } else {
      /* ---------- Normal scorecard ---------- */
      const { score, total, percent, results, attempts, marksEarned, marksPossible } = resp;
      const pendingReview = !!(resp && resp.pendingEvaluation);
      const isPerfect = score === total && !pendingReview;
      const isPass = percent >= 60;
      const emoji = isPerfect ? '🏆' : pendingReview ? '⏳' : isPass ? '🎉' : '📚';
      const headline = isPerfect ? 'Perfect Score!'
                      : pendingReview ? 'Submitted — Pending Review'
                      : isPass ? 'Well done!' : 'Keep practicing!';

      let rHtml = `<div class="quiz-result-hero ${isPass ? 'pass' : 'fail'}">
        <div class="quiz-result-emoji">${emoji}</div>
        <div class="quiz-result-score">${score} / ${total}</div>
        <div class="quiz-result-pct">${percent}%${marksPossible ? ` · ${marksEarned} / ${marksPossible} marks` : ''}</div>
        <div class="quiz-result-headline">${headline}</div>
        ${pendingReview ? `<p style="margin-top:10px;font-size:12.5px;color:var(--text-tertiary);">
          Your subjective answers are awaiting instructor review. Final marks will be visible after review.
        </p>` : ''}
        <div style="font-size:12px;color:var(--text-tertiary);margin-top:6px;">Attempt #${attempts}</div>
      </div>`;

      st.quiz.forEach((q, qi) => {
        const r = results[qi];
        const ok = r.correct;
        const itemPending = r.manualReview === true;
        const cls = itemPending ? 'pending' : (ok ? 'ok' : 'bad');
        const badge = itemPending
          ? '<i class="fas fa-hourglass-half"></i>'
          : (ok ? '<i class="fas fa-check"></i>' : '<i class="fas fa-times"></i>');
        rHtml += `<div class="quiz-result-item ${cls}">
          <div class="quiz-result-head">
            <span class="quiz-result-badge ${cls}">${badge}</span>
            <strong>Q${qi + 1}.</strong>
            <span class="latex-content">${escapeHtml(q.question)}</span>
          </div>
          <div class="quiz-result-body">
            ${renderResultDetail(q, r)}
            ${r.explanation ? `<div class="quiz-explain"><i class="fas fa-lightbulb"></i> <span class="latex-content">${escapeHtml(r.explanation)}</span></div>` : ''}
          </div>
        </div>`;
      });
      bodyHtml = `<div class="quiz-exam-body-inner">${rHtml}</div>`;
    }
  }

  /* ---------- Footer ---------- */
  let footerHtml;
  if (st.previewMode) {
    footerHtml = `
      <footer class="quiz-exam-footer">
        <div class="quiz-exam-footer-left">
          <span class="quiz-exam-warning-note" style="background:rgba(99,102,241,.1);color:var(--brand-600);border-color:rgba(99,102,241,.25);">
            <i class="fas fa-eye"></i> Preview mode — no proctoring, no submission.
          </span>
        </div>
        <button type="button" class="btn btn-primary" onclick="exitQuizSession()">
          <i class="fas fa-times"></i> Close Preview
        </button>
      </footer>`;
  } else if (!st.submitted) {
    const isLast  = st.displayIndex >= st.questionOrder.length - 1;
    const isFirst = st.displayIndex === 0;

    footerHtml = `
      <footer class="quiz-exam-footer">
        <div class="quiz-exam-footer-left">
          <button type="button" class="btn btn-outline" onclick="requestQuitExam()">
            <i class="fas fa-times"></i> Quit Exam
          </button>
          ${st.forwardOnly
            ? `<span class="quiz-exam-warning-note" style="background:rgba(239,68,68,.1);color:var(--rose-600);border-color:rgba(239,68,68,.3);">
                 <i class="fas fa-lock"></i> Forward-only · Question ${st.displayIndex + 1} of ${st.questionOrder.length}
               </span>`
            : `<span class="quiz-exam-warning-note" style="background:rgba(16,185,129,.1);color:var(--emerald-600);border-color:rgba(16,185,129,.3);">
                 <i class="fas fa-arrows-left-right"></i> Free navigation · Question ${st.displayIndex + 1} of ${st.questionOrder.length}
               </span>`}
        </div>
        <div class="quiz-exam-nav-actions">
          ${!st.forwardOnly && !isFirst
            ? `<button type="button" class="btn btn-outline btn-lg" onclick="prevExamQuestion()">
                 <i class="fas fa-arrow-left"></i> Previous
               </button>`
            : ''}
          ${st.forwardOnly && !isLast
            ? `<button type="button" class="btn btn-primary btn-lg" onclick="nextExamQuestion()">
                 <i class="fas fa-arrow-right"></i> Next Question
               </button>`
            : ''}
          ${isLast
            ? `<button type="button" class="btn btn-primary btn-lg" onclick="submitQuiz()">
                 <i class="fas fa-paper-plane"></i> Submit Test
               </button>`
            : ''}
        </div>
      </footer>`;
  } else {
    /* ⭐ After a submission, only show Retake if the student still
       has an attempt left (maxAttempts === 0 means unlimited). */
    const resp        = st.response || {};
    const cap         = Number(resp.maxAttempts) || 0;
    const usedSoFar   = Number(resp.attemptsUsed) || Number(resp.attempts) || 0;
    const canRetake   = (cap === 0) || (usedSoFar < cap);

    footerHtml = `
      <footer class="quiz-exam-footer">
        <div class="quiz-exam-footer-left"></div>
        <div style="display:flex;gap:10px;flex-wrap:wrap;">
          ${canRetake ? `
            <button type="button" class="btn btn-outline" onclick="retakeQuiz()">
              <i class="fas fa-redo"></i> Retake
            </button>` : ''}
          <button type="button" class="btn btn-primary" onclick="exitQuizSession()">
            <i class="fas fa-check"></i> Done
          </button>
        </div>
      </footer>`;
  }

  shell.innerHTML = headerHtml + `<div class="quiz-exam-body">${bodyHtml}</div>` + footerHtml;
  renderMathIn(shell.querySelector('.quiz-exam-body'));

  /* Re-arm the timer's countdown display after a fresh render */
  if (!st.submitted && st.durationSeconds) {
    const serverNow = Date.now() + _examClockOffsetMs;
    const deadlineMs = st.serverStartedAt + st.durationSeconds * 1000;
    const remaining = Math.max(0, Math.floor((deadlineMs - serverNow) / 1000));
    const el = document.getElementById('quizTimerDisplay');
    if (el) el.textContent = formatDuration(remaining);
  }
}


/* ---- Forward-only: single-question renderer ---- */
function _renderSingleExamQuestion(st) {
  const displayIdx = st.displayIndex;
  const originalIdx = st.questionOrder[displayIdx];
  const q = st.quiz[originalIdx];
  if (!q) return '';

  const qType = q.type || 'single';
  const a = st.answers[originalIdx];
  const isAnswered = _isQuestionAnswered(q, a);
  const locked = !!st.questionLocked[originalIdx];

  return `<div class="quiz-play-card ${isAnswered ? 'answered' : ''}${locked ? ' locked' : ''}"
              data-original-index="${originalIdx}"
              data-display-index="${displayIdx}">
    <div class="quiz-play-qnum">
      Question ${displayIdx + 1} of ${st.questionOrder.length}
      <span class="quiz-qtype-tag">${questionTypeLabel(qType)}</span>
      <span class="quiz-qmark-tag">+${q.marks || 4}${q.negativeMarks ? ' / ' + q.negativeMarks : ''}</span>
      ${isAnswered ? '<span class="quiz-answered-tag"><i class="fas fa-check-circle"></i> Answered</span>' : ''}
      ${locked ? '<span class="quiz-answered-tag" style="color:var(--rose-500);"><i class="fas fa-lock"></i> Locked</span>' : ''}
    </div>
    <h4 class="quiz-play-question latex-content">${escapeHtml(q.question)}</h4>
    ${locked ? `<div class="quiz-locked-note"><i class="fas fa-lock"></i> This answer has been locked in.</div>` : ''}
    ${renderStudentAnswerAreaShuffled(q, originalIdx, st)}
  </div>`;
}

/* ---- Non forward-only: render every question as before ---- */
function _renderAllExamQuestions(st) {
  let html = '';
  st.quiz.forEach((q, qi) => {
    const qType = q.type || 'single';
    const a = st.answers[qi];
    const isAnswered = _isQuestionAnswered(q, a);
    html += `<div class="quiz-play-card ${isAnswered ? 'answered' : ''}" data-original-index="${qi}">
      <div class="quiz-play-qnum">
        Question ${qi + 1} of ${st.quiz.length}
        <span class="quiz-qtype-tag">${questionTypeLabel(qType)}</span>
        <span class="quiz-qmark-tag">+${q.marks || 4}${q.negativeMarks ? ' / ' + q.negativeMarks : ''}</span>
        ${isAnswered ? '<span class="quiz-answered-tag"><i class="fas fa-check-circle"></i> Answered</span>' : ''}
      </div>
      <h4 class="quiz-play-question latex-content">${escapeHtml(q.question)}</h4>
      ${renderStudentAnswerAreaShuffled(q, qi, st)}
    </div>`;
  });
  return html;
}

/* ---- Answer area that respects per-question option order ---- */
function renderStudentAnswerAreaShuffled(q, qi, st) {
  const qType = q.type || 'single';
  const ans = st.answers[qi];

  if (qType === 'single' || qType === 'multiple') {
    const inputType = qType === 'single' ? 'radio' : 'checkbox';
    const name = `pq-${qi}`;
    const order = (st.optionOrders && st.optionOrders[qi]) ||
                  Array.from({ length: (q.options || []).length }, (_, i) => i);
    const locked = !!st.questionLocked[qi];

    return `<div class="quiz-play-options">
      ${order.map((origOptIdx, displayPos) => {
        const opt = (q.options || [])[origOptIdx] || '';
        const checked = qType === 'single'
          ? (ans === origOptIdx || (Array.isArray(ans) && ans[0] === origOptIdx))
          : (Array.isArray(ans) && ans.includes(origOptIdx));
        const letter = String.fromCharCode(65 + displayPos);
        return `<label class="quiz-play-option ${checked ? 'selected' : ''}${locked ? ' locked' : ''}" data-orig-opt-idx="${origOptIdx}">
          <input type="${inputType}" name="${name}" ${checked ? 'checked' : ''} ${locked ? 'disabled' : ''} style="display:none;"
                 onchange="selectQuizAnswerMulti(${qi}, ${origOptIdx}, this.checked, '${qType}')">
          <span class="quiz-play-letter">${letter}</span>
          <span class="quiz-play-text latex-content">${escapeHtml(opt)}</span>
        </label>`;
      }).join('')}
    </div>`;
  }

  /* Non-MCQ types are unchanged */
  return renderStudentAnswerArea(q, qi);
}

/* ---- Advance to the next question (forward-only) ---- */
function nextExamQuestion() {
  const st = quizPlayerState;
  if (!st || !st.forwardOnly || st.submitted) return;

  const currentOriginalIdx = st.questionOrder[st.displayIndex];

  /* Record the time spent on the current question */
  _recordQuestionTime(currentOriginalIdx);

  /* Lock it — cannot be revisited */
  st.questionLocked[currentOriginalIdx] = true;

  /* Advance */
  st.displayIndex = Math.min(st.displayIndex + 1, st.questionOrder.length - 1);

  /* Reset entry timer for the new question */
  _examQuestionEnteredAt = Date.now();

  renderQuizExamShell();

  /* Scroll back to top */
  const body = document.querySelector('.quiz-exam-body');
  if (body) body.scrollTop = 0;
}

/* ---- Time tracking ---- */
function _recordQuestionTime(originalIdx) {
  if (!quizPlayerState) return;
  if (_examQuestionEnteredAt > 0) {
    const elapsed = Math.max(0, Math.round((Date.now() - _examQuestionEnteredAt) / 1000));
    const prev = Number(quizPlayerState.timeSpentPerQuestion[originalIdx]) || 0;
    quizPlayerState.timeSpentPerQuestion[originalIdx] = prev + elapsed;
  }
  _examQuestionEnteredAt = Date.now();
}

/* ============================================================
   PROCTORING — Event handlers
   ============================================================ */
function _onExamVisibilityChange() {
  if (!quizPlayerState || !quizPlayerState.examStarted || quizPlayerState.submitted) return;
  if (document.hidden) _handleExamViolation('You left the exam tab.');
}

function _onExamWindowBlur() {
  if (!quizPlayerState || !quizPlayerState.examStarted || quizPlayerState.submitted) return;
  if (document.querySelector('.modal-overlay.active')) return;
  if (window.__examAllowBlur) return;   // file picker grace period
  _handleExamViolation('The exam window lost focus.');
}

/* Allow a brief window-blur without triggering a proctoring violation.
   Used when the student opens the OS file picker for subjective uploads.
   The flag auto-clears after 8 s — this is CRITICAL: if the student
   cancels the file dialog, the input's onchange never fires, and
   without this timer the proctoring would stay disabled for the rest
   of the exam. */
function allowExamBlurBriefly() {
  window.__examAllowBlur = true;
  clearTimeout(window.__examBlurTimer);
  window.__examBlurTimer = setTimeout(() => {
    window.__examAllowBlur = false;
  }, 8000);
}

function _onExamFullscreenChange() {
  if (!quizPlayerState || !quizPlayerState.examStarted || quizPlayerState.submitted) return;
  if (!quizPlayerState.fullscreenArmed) return;
  const stillFs = document.fullscreenElement || document.webkitFullscreenElement;
  if (!stillFs) _handleExamViolation('You exited full-screen mode.');
}

function _onExamBeforeUnload(e) {
  if (!quizPlayerState || !quizPlayerState.examStarted || quizPlayerState.submitted) return;
  persistQuizAnswers();
  e.preventDefault();
  e.returnValue = '';
  return '';
}

function _handleExamViolation(reason) {
  const st = quizPlayerState;
  if (!st || st.submitted || st.violationHandling) return;

  st.violationHandling = true;
  st.strikes = (st.strikes || 0) + 1;
  st.violations.push({ reason, at: Date.now() });

  if (st.strikes > QUIZ_PROCTOR_MAX_STRIKES) {
    _autoSubmitForViolation(reason);
  } else {
    _showViolationWarning(reason, st.strikes);
  }

  setTimeout(() => { if (quizPlayerState) quizPlayerState.violationHandling = false; }, 1500);
}

function _resetViolationModalButtons() {
  const resumeBtn = document.getElementById('quizViolationResumeBtn');
  if (resumeBtn) {
    resumeBtn.textContent = 'Resume Exam';
    resumeBtn.className = 'btn btn-primary btn-block';
    resumeBtn.setAttribute('onclick', 'resumeExamAfterViolation()');
  }
}

function _showViolationWarning(reason, strikeNumber) {
  const text = document.getElementById('quizViolationText');
  const box  = document.getElementById('quizViolationBox');

  if (text) {
    text.textContent =
      `${reason} This is your final warning — one more violation will instantly auto-submit your exam.`;
  }
  if (box) {
    box.innerHTML = `
      <div class="violation-warning-row">
        <span class="violation-warning-label">Strike</span>
        <span class="violation-warning-value">${strikeNumber} of ${QUIZ_PROCTOR_MAX_STRIKES}</span>
      </div>
      <div class="violation-warning-row">
        <span class="violation-warning-label">Rule</span>
        <span class="violation-warning-value">Do not switch tabs or windows during the exam.</span>
      </div>`;
  }
  _resetViolationModalButtons();
  persistQuizAnswers();
  openModal('quizViolationModal');
}

function resumeExamAfterViolation() {
  closeModal('quizViolationModal');
  try {
    if (!document.fullscreenElement && !document.webkitFullscreenElement) {
      const el = document.documentElement;
      const req = el.requestFullscreen || el.webkitRequestFullscreen;
      if (req) { const p = req.call(el); if (p && p.catch) p.catch(() => {}); }
    }
  } catch (e) {}
}

async function _autoSubmitForViolation(reason) {
  const st = quizPlayerState;
  if (!st) return;
  st.autoSubmitted = true;
  showToast('⚠️ Auto-submitting due to proctoring violation…', 'error');
  await new Promise(r => setTimeout(r, 400));
  await submitQuiz({ auto: true });
}

function requestQuitExam() {
  const st = quizPlayerState;
  if (!st) return;

  st.examStarted = false;
  const ok = confirm(
    'Quit the exam?\n\n' +
    'Your answers will be saved locally, but no score will be recorded.'
  );
  if (ok) {
    persistQuizAnswers();
    exitQuizSession();
    return;
  }
  try {
    if (!document.fullscreenElement && !document.webkitFullscreenElement) {
      const el = document.documentElement;
      const req = el.requestFullscreen || el.webkitRequestFullscreen;
      if (req) { const p = req.call(el); if (p && p.catch) p.catch(() => {}); }
    }
  } catch (e) {}
  setTimeout(() => { if (quizPlayerState) quizPlayerState.examStarted = true; }, 1000);
}

/* ============================================================
   ANTI-CHEAT — Input restrictions
   ============================================================ */
function _inExam() {
  return quizPlayerState && quizPlayerState.examStarted && !quizPlayerState.submitted;
}
function _blockContextMenu(e) {
  if (!_inExam()) return;
  e.preventDefault();
  return false;
}
function _blockCopy(e) {
  if (!_inExam()) return;
  if (e.target && e.target.closest && e.target.closest('input, textarea, [contenteditable]')) return;
  e.preventDefault();
  return false;
}
function _blockSelectStart(e) {
  if (!_inExam()) return;
  if (e.target && e.target.closest && e.target.closest('input, textarea, [contenteditable]')) return;
  e.preventDefault();
  return false;
}
function _blockDrag(e) {
  if (!_inExam()) return;
  e.preventDefault();
}
function _blockDevKeys(e) {
  if (!_inExam()) return;

  if (e.key === 'F12') { e.preventDefault(); e.stopPropagation(); return false; }
  if ((e.ctrlKey || e.metaKey) && e.shiftKey &&
      ['I','J','C','i','j','c'].includes(e.key)) {
    e.preventDefault(); e.stopPropagation(); return false;
  }
  if ((e.ctrlKey || e.metaKey) && ['u','U','s','S','p','P'].includes(e.key)) {
    e.preventDefault(); e.stopPropagation(); return false;
  }
  if ((e.ctrlKey || e.metaKey) && (e.key === 'k' || e.key === 'K')) {
    e.preventDefault(); e.stopPropagation(); return false;
  }
  if ((e.ctrlKey || e.metaKey) && ['a','c','v','x','A','C','V','X'].includes(e.key)) {
    if (e.target && e.target.closest && e.target.closest('input, textarea, [contenteditable]')) return;
    e.preventDefault(); e.stopPropagation(); return false;
  }
}

/* ============================================================
   SUBMIT / EXIT / RETAKE
   ============================================================ */
async function submitQuiz(opts = {}) {
  const st = quizPlayerState; if (!st) return;
  if (st.previewMode) return showToast('Preview mode — nothing submitted.', 'info');
  if (st.submitted) return;

  /* ⭐ FIX: In-flight guard — the timer-expiry auto-submit and a
     manual click can fire within the same tick and both reach the
     server, causing the second POST to be rejected with
     ALREADY_SUBMITTED. A 30 s timestamp guard blocks the duplicate
     without needing try/finally plumbing (30 s is far longer than
     any real submit round trip). */
  const _now = Date.now();
  if (st._submitGuardUntil && _now < st._submitGuardUntil) return;
  st._submitGuardUntil = _now + 30000;

  const auto = !!opts.auto;

  if (!auto) {
    /* Validate that every question has an answer */
    for (let i = 0; i < st.quiz.length; i++) {
      const q = st.quiz[i];
      const a = st.answers[i];
      if (q.type === 'integer' || q.type === 'numerical') {
        if (a === '' || a === null || a === undefined || isNaN(Number(a))) {
          return showToast(`Please answer Q${i + 1}.`, 'error');
        }
      } else if (q.type === 'subjective') {
        if (!Array.isArray(a) || a.length === 0) {
          return showToast(`Please upload at least one photo for Q${i + 1}.`, 'error');
        }
        if (a.some(u => u && u.uploading)) {
          return showToast(`Please wait for Q${i + 1} uploads to finish.`, 'error');
        }
        if (a.some(u => !u || !u.url)) {
          return showToast(`Q${i + 1}: some photos failed to upload. Remove and retry.`, 'error');
        }
      } else if (q.type === 'matrix') {
        const rows = q.matrixRows || [];
        if (!Array.isArray(a) ||
            a.filter(x => x !== undefined && x !== null && x !== '').length < rows.length) {
          return showToast(`Please match all items in Q${i + 1}.`, 'error');
        }
      } else {
        if (Array.isArray(a) ? a.length === 0 : (a === null || a === undefined || a === -1)) {
          return showToast(`Please answer Q${i + 1}.`, 'error');
        }
      }
    }
  }

  /* ⭐ Record time on the final question before submitting */
  if (st.forwardOnly && st.questionOrder && st.questionOrder.length > 0) {
    const lastOrigIdx = st.questionOrder[st.displayIndex];
    _recordQuestionTime(lastOrigIdx);
  } else {
    /* Non forward-only: credit remaining time to the question that was
       being viewed when the user clicked submit. We approximate by
       crediting _examQuestionEnteredAt to the currently-visible card. */
    _recordQuestionTime(0);
  }

  st.examStarted = false;

  try {
    const res = await fetch(
      `/api/user/quiz/${st.courseId}/${st.materialId}`,
      {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          userId: currentUser._id,
          answers: st.answers,
          timeSpentPerQuestion: st.timeSpentPerQuestion,
          autoSubmitted: auto
        })
      }
    );
    const data = await res.json();

    if (data.success) {
      st.submitted = true;
      st.response = data;

      // ⭐ XP + level-up feedback
      if (data.xpResult && data.xpResult.gained > 0) {
        showToast(`+${data.xpResult.gained} XP · ${data.xpResult.reason}`, 'success');
      }
      if (data.xpResult && data.xpResult.leveledUp) {
        setTimeout(() => {
          showToast(`🎉 Level ${data.xpResult.level} — ${data.xpResult.levelName}!`, 'success');
        }, 1200);
      }

      stopQuizTimer();
      clearQuizAnswers(st.materialId);
      try { localStorage.removeItem('aero_quiz_start_' + st.materialId); } catch (e) {}
      try { clearSavedQuizDraft(st.materialId); } catch (e) {}

      if (!currentUser.quizResults) currentUser.quizResults = {};
      currentUser.quizResults[st.materialId] = {
        score: data.score, total: data.total, percent: data.percent,
        marksEarned: data.marksEarned, marksPossible: data.marksPossible,
        attempts: data.attempts, lastAttemptAt: new Date().toISOString()
      };
      saveSessionUser(currentUser);
      _analyticsCacheAt = 0;

      _detachAllProctorListeners();
      exitFullscreenNow();

      renderQuizExamShell();

      if (auto) {
        showToast('⚠️ Exam auto-submitted (time up or proctoring violation).', 'error');
      } else if (data.pendingEvaluation) {
        showToast('✅ Submitted. Subjective answers are pending instructor review.', 'success');
      } else {
        const pct = data.percent;
        if (pct === 100)     showToast('🏆 Perfect!', 'success');
        else if (pct >= 60)  showToast(`🎉 Scored ${data.score}/${data.total}!`, 'success');
        else                 showToast(`📚 Scored ${data.score}/${data.total}.`, 'info');
      }
    } else {
      st.examStarted = true;
      if (data.code === 'TIME_EXPIRED') {
        stopQuizTimer();
        _detachAllProctorListeners();
        exitFullscreenNow();
        st.submitted = true;
        st.response = { score: 0, total: 0, percent: 0, results: st.quiz.map(() => ({ correct: false })), attempts: 0, marksEarned: 0, marksPossible: 0 };
        renderQuizExamShell();
        showToast('⏰ Attempt expired before submission.', 'error');
      } else {
        showToast(data.message || 'Failed.', 'error');
      }
      /* ⭐ FIX: release the in-flight guard so the student can retry. */
      st._submitGuardUntil = 0;
    }
  } catch (err) {
    console.error('[submitQuiz]', err);
    st.examStarted = true;
    showToast('Server error.', 'error');
    /* ⭐ FIX: release the in-flight guard so the student can retry. */
    st._submitGuardUntil = 0;
  }
}

function exitFullscreenNow() {
  try {
    if (document.fullscreenElement && document.exitFullscreen) {
      const p = document.exitFullscreen();
      if (p && p.catch) p.catch(() => {});
    } else if (document.webkitFullscreenElement && document.webkitExitFullscreen) {
      document.webkitExitFullscreen();
    }
  } catch (e) {}
}

function exitQuizSession() {
  const st = quizPlayerState;
  const returnCourseId = st ? st.courseId : null;
  const wasPreview = st ? st.previewMode : false;

  _detachAllProctorListeners();
  exitFullscreenNow();
  stopQuizTimer();

  const shell = document.getElementById('quizExamShell');
  if (shell) {
    shell.style.display = 'none';
    shell.innerHTML = '';
    shell.setAttribute('aria-hidden', 'true');
  }
  document.body.style.overflow = '';
  quizPlayerState = null;

  if (!wasPreview && returnCourseId && currentUser && currentUser.role === 'student') {
    try { renderCourseDetail(returnCourseId); } catch (e) {}
  }
}

async function retakeQuiz() {
  const st = quizPlayerState;
  if (!st) return;
  const courseId = st.courseId;
  const materialId = st.materialId;

  /* ⭐ Purge the previous server-side session so /start creates a
     fresh one — otherwise the new attempt inherits the old timer. */
  try {
    await fetchJSON(
      `/api/user/quiz/${courseId}/${materialId}/reset`,
      {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ userId: currentUser._id })
      }
    );
  } catch (e) {
    console.warn('[retakeQuiz] session reset failed:', e.message);
  }

  clearQuizAnswers(materialId);
  try { localStorage.removeItem('aero_quiz_start_' + materialId); } catch (e) {}
  exitQuizSession();
  openQuizPlayer(courseId, materialId);
}
/* ============================================================
   Quiz exam — targeted DOM updates (avoid full re-render)
   ============================================================ */
function _isQuestionAnswered(q, a) {
  const qType = q.type || 'single';
  if (qType === 'integer' || qType === 'numerical') {
    return a !== '' && a !== null && a !== undefined && !isNaN(Number(a));
  }
  if (qType === 'subjective') {
    // Answered if at least one photo uploaded AND no upload still in progress
    if (!Array.isArray(a) || a.length === 0) return false;
    return a.every(u => u && u.url && !u.uploading);
  }
  if (qType === 'matrix') {
    const rows = q.matrixRows || [];
    return Array.isArray(a) &&
      a.filter(x => x !== undefined && x !== null && x !== '').length >= rows.length;
  }
  return Array.isArray(a) ? a.length > 0 : (a >= 0);
}

function updateQuizProgressUI() {
  const st = quizPlayerState;
  if (!st) return;
  const answered = st.quiz.reduce((s, q, i) => s + (_isQuestionAnswered(q, st.answers[i]) ? 1 : 0), 0);

  const textEl = document.querySelector('.quiz-exam-progress-text');
  if (textEl) textEl.innerHTML = `<strong>${answered}</strong> / ${st.quiz.length} answered`;

  const fillEl = document.querySelector('.quiz-exam-progress-fill');
  if (fillEl) {
    fillEl.style.width = st.quiz.length > 0
      ? ((answered / st.quiz.length) * 100) + '%'
      : '0%';
  }
}

function updateQuizQuestionCard(qi) {
  const st = quizPlayerState;
  if (!st) return;

  /* ⭐ FIX: Find the card by its `data-original-index`, NOT by
     positional index. In forward-only mode only ONE card is in the
     DOM at a time, so `document.querySelectorAll(...)[qi]` was
     always undefined for every question after the first — the
     visual selection never updated. */
  const card = document.querySelector(
    `.quiz-exam-body-inner .quiz-play-card[data-original-index="${qi}"]`
  );
  if (!card) return;

  const q          = st.quiz[qi];
  const a          = st.answers[qi];
  const qType      = q.type || 'single';
  const isAnswered = _isQuestionAnswered(q, a);

  card.classList.toggle('answered', isAnswered);

  const qnum = card.querySelector('.quiz-play-qnum');
  if (qnum) {
    const existingTag = qnum.querySelector('.quiz-answered-tag');
    if (isAnswered && !existingTag) {
      const span = document.createElement('span');
      span.className = 'quiz-answered-tag';
      span.innerHTML = '<i class="fas fa-check-circle"></i> Answered';
      qnum.appendChild(span);
    } else if (!isAnswered && existingTag) {
      existingTag.remove();
    }
  }

  if (qType === 'single' || qType === 'multiple') {
    const opts = card.querySelectorAll('.quiz-play-option');
    opts.forEach((opt) => {
      /* ⭐ FIX: compare against the ORIGINAL option index stored on
         the element, NOT the DOM position — they differ whenever the
         option order was shuffled server-side. */
      const origOptIdx = parseInt(opt.dataset.origOptIdx, 10);
      if (Number.isNaN(origOptIdx)) return;

      const selected = qType === 'single'
        ? (a === origOptIdx || (Array.isArray(a) && a[0] === origOptIdx))
        : (Array.isArray(a) && a.includes(origOptIdx));

      opt.classList.toggle('selected', selected);
      const input = opt.querySelector('input');
      if (input) input.checked = selected;
    });
  }
}

/* ============================================================
   ANSWER INTERACTION
   ============================================================ */
function renderStudentAnswerArea(q, qi) {
  const st = quizPlayerState;
  const ans = st.answers[qi];
  const qType = q.type || 'single';

  if (qType === 'single' || qType === 'multiple') {
    const inputType = qType === 'single' ? 'radio' : 'checkbox';
    const name = `pq-${qi}`;
    return `<div class="quiz-play-options">
      ${(q.options || []).map((opt, oi) => {
        const checked = qType === 'single'
          ? (ans === oi || (Array.isArray(ans) && ans[0] === oi))
          : (Array.isArray(ans) && ans.includes(oi));
        return `<label class="quiz-play-option ${checked ? 'selected' : ''}">
          <input type="${inputType}" name="${name}" ${checked ? 'checked' : ''} style="display:none;"
                 onchange="selectQuizAnswerMulti(${qi}, ${oi}, this.checked, '${qType}')">
          <span class="quiz-play-letter">${String.fromCharCode(65 + oi)}</span>
          <span class="quiz-play-text latex-content">${escapeHtml(opt)}</span>
        </label>`;
      }).join('')}
    </div>`;
  }

  if (qType === 'integer') {
    return `<div class="form-group" style="margin-top:8px;">
      <label>Your Answer</label>
      <input type="number" step="any" placeholder="Enter a number"
             value="${ans === '' ? '' : (ans ?? '')}"
             oninput="selectQuizAnswerInteger(${qi}, this.value)">
    </div>`;
  }

  if (qType === 'numerical') {                                       // ⭐ NEW
    return `<div class="form-group" style="margin-top:8px;">
      <label>Your Answer <span class="hint" style="display:inline;">(any value inside the accepted range counts as correct)</span></label>
      <input type="number" step="any" placeholder="Enter a numeric value"
             value="${ans === '' ? '' : (ans ?? '')}"
             oninput="selectQuizAnswerInteger(${qi}, this.value)">
    </div>`;
  }

  if (qType === 'subjective') {                                      // ⭐ NEW
    const uploads = Array.isArray(ans) ? ans : [];
    const maxM = q.subjectiveMaxMarks || 10;
    const instr = q.subjectiveInstructions || '';
    return `
      <div class="subjective-answer-block">
        ${instr ? `<div class="subjective-instructions"><i class="fas fa-info-circle"></i> ${escapeHtml(instr)}</div>` : ''}
        <div class="subjective-meta-row">
          <span class="subjective-max-badge"><i class="fas fa-star"></i> ${maxM} marks · Admin evaluated</span>
        </div>

        <!-- ⭐ Two buttons so mobile users can either shoot a photo or attach a PDF -->
        <div class="subjective-upload-row">
          <label class="subjective-upload-btn">
            <input type="file"
                   accept="image/*,.heic,.heif"
                   capture="environment"
                   multiple
                   style="display:none;"
                   onmousedown="allowExamBlurBriefly();"
                   onfocus="allowExamBlurBriefly();"
                   onchange="handleSubjectiveUpload(${qi}, this, 'image');">
            <i class="fas fa-camera"></i>
            <span>Take / Choose Photo</span>
          </label>

          <label class="subjective-upload-btn subjective-upload-btn--pdf">
            <input type="file"
                   accept="application/pdf,.pdf"
                   multiple
                   style="display:none;"
                   onmousedown="allowExamBlurBriefly();"
                   onfocus="allowExamBlurBriefly();"
                   onchange="handleSubjectiveUpload(${qi}, this, 'pdf');">
            <i class="fas fa-file-pdf"></i>
            <span>Attach PDF Scan</span>
          </label>
        </div>

        <p class="subjective-upload-hint">
          <i class="fas fa-info-circle"></i>
          Images (<strong>JPG · PNG · HEIC</strong>) or <strong>PDF</strong> · max <strong>25 MB</strong> per file · up to <strong>10 files</strong>
        </p>

        <div class="subjective-uploads" id="subjectiveUploads-${qi}">
          ${uploads.map((u, idx) => renderSubjectiveUpload(u, qi, idx)).join('')}
        </div>
      </div>`;
  }

  if (qType === 'matrix') {
    const left  = q.matrixLeftItems  || [];
    const right = q.matrixRightItems || [];
    const chosen = Array.isArray(ans) ? ans : [];
    return `
      <div class="matrix-match-student">
        ${left.map((item, li) => `
          <div class="matrix-match-row">
            <div class="matrix-match-item latex-content">
              <span class="quiz-play-letter">${String.fromCharCode(65 + li)}</span>
              <span>${escapeHtml(item)}</span>
            </div>
            <span class="matrix-arrow">→</span>
            <select onchange="selectQuizAnswerMatrix(${qi}, ${li}, this.value)">
              <option value="">— Select match —</option>
              ${right.map((rItem, ri) => {
                const label = ['P','Q','R','S','T','U','V','W'][ri] || (ri + 1);
                return `<option value="${ri}" ${Number(chosen[li]) === ri ? 'selected' : ''}>${label}. ${escapeHtml(rItem).slice(0, 60)}</option>`;
              }).join('')}
            </select>
          </div>
        `).join('')}
      </div>`;
  }
  return '';
}

function renderResultDetail(q, r) {
  const qType = q.type || 'single';
  if (qType === 'single' || qType === 'multiple') {
    const chosenIdx = Array.isArray(r.chosen) ? r.chosen : (r.chosen != null ? [r.chosen] : []);
    const correctIdx = r.correctIndexes || [];
    const fmt = idxs => idxs.length === 0
      ? '<em>Not answered</em>'
      : idxs.map(i => `<span class="latex-content">${escapeHtml(q.options[i] || '—')}</span>`).join(', ');
    return `
      <div class="quiz-answer-row"><span class="quiz-answer-label">Your answer:</span>
        <span class="${r.correct ? 'ok-text' : 'bad-text'}">${fmt(chosenIdx)}</span>
      </div>
      ${!r.correct ? `<div class="quiz-answer-row"><span class="quiz-answer-label">Correct:</span>
        <span class="ok-text">${fmt(correctIdx)}</span></div>` : ''}
    `;
  }
  if (qType === 'integer') {
    const tol = Number(r.integerTolerance) || 0;
    const tolStr = tol > 0 ? ` (±${tol})` : '';
    return `
      <div class="quiz-answer-row"><span class="quiz-answer-label">Your answer:</span>
        <span class="${r.correct ? 'ok-text' : 'bad-text'}">${r.chosen ?? '—'}</span>
      </div>
      ${!r.correct ? `<div class="quiz-answer-row"><span class="quiz-answer-label">Correct:</span>
        <span class="ok-text">${r.integerAnswer}${tolStr}</span></div>` : ''}
    `;
  }

  if (qType === 'numerical') {                                       // ⭐ NEW
    const min = r.rangeMin;
    const max = r.rangeMax;
    const chosen = r.chosen;
    const hasAns = chosen !== '' && chosen !== null && chosen !== undefined && !isNaN(Number(chosen));
    return `
      <div class="quiz-answer-row"><span class="quiz-answer-label">Your answer:</span>
        <span class="${r.correct ? 'ok-text' : (hasAns ? 'bad-text' : '')}">
          ${hasAns ? chosen : '—'}
        </span>
      </div>
      <div class="quiz-answer-row"><span class="quiz-answer-label">Accepted range:</span>
        <span class="ok-text">${min} – ${max}</span>
      </div>
    `;
  }

  if (qType === 'subjective') {                                      // ⭐ NEW
    const uploads = Array.isArray(r.chosen) ? r.chosen : [];
    const evals   = quizPlayerState?.response?.subjectiveEvaluations || {};
    const ev      = evals[String(quizPlayerState ? quizPlayerState.quiz.indexOf(q) : -1)] || null;
    return `
      <div class="quiz-answer-row">
        <span class="quiz-answer-label">Your uploaded solution(s):</span>
        <span>${uploads.length} photo${uploads.length === 1 ? '' : 's'}</span>
      </div>
      ${uploads.length > 0 ? `
        <div class="subjective-result-thumbs">
          ${uploads.map(u => `<a href="${escapeHtml(u.url)}" target="_blank" rel="noopener">
            <img src="${escapeHtml(u.url)}" alt="answer" loading="lazy" decoding="async">
          </a>`).join('')}
        </div>` : '<div class="quiz-answer-row"><em>No photos uploaded.</em></div>'}
      <div class="quiz-answer-row subjective-pending-note">
        <i class="fas fa-hourglass-half"></i>
        <span>${ev ? `Marks awarded: <strong>${ev.awardedMarks} / ${r.maxMarks}</strong>${ev.feedback ? ' — ' + escapeHtml(ev.feedback) : ''}` : 'Pending admin evaluation'}</span>
      </div>
    `;
  }
  if (qType === 'matrix') {
    const rows = r.matrixRows || [];
    const chosen = Array.isArray(r.chosen) ? r.chosen : [];
    const rightLabels = ['P','Q','R','S','T','U','V','W'];
    return `
      <table class="matrix-result-table">
        <thead><tr><th>List-I</th><th>Your Match</th><th>Correct</th></tr></thead>
        <tbody>
          ${rows.map((row, ri) => {
            const ok = Number(chosen[ri]) === Number(row.correctIndex);
            return `<tr class="${ok ? 'ok-row' : 'bad-row'}">
              <td class="latex-content">${String.fromCharCode(65 + ri)}. ${escapeHtml(row.text)}</td>
              <td>${chosen[ri] != null && chosen[ri] !== '' ? (rightLabels[chosen[ri]] || '—') : '—'}</td>
              <td>${rightLabels[row.correctIndex] || '—'}</td>
            </tr>`;
          }).join('')}
        </tbody>
      </table>`;
  }
  return '';
}

function selectQuizAnswerMulti(qi, oi, isChecked, type) {
  const st = quizPlayerState; if (!st || st.submitted) return;
  if (type === 'single') st.answers[qi] = oi;
  else {
    let arr = Array.isArray(st.answers[qi]) ? st.answers[qi].slice() : [];
    if (isChecked) { if (!arr.includes(oi)) arr.push(oi); }
    else arr = arr.filter(x => x !== oi);
    st.answers[qi] = arr;
  }
  persistQuizAnswers();
  updateQuizQuestionCard(qi);
  updateQuizProgressUI();
}
function selectQuizAnswerInteger(qi, val) {
  const st = quizPlayerState; if (!st || st.submitted) return;
  st.answers[qi] = val;
  persistQuizAnswers();
  updateQuizQuestionCard(qi);
  updateQuizProgressUI();
}
function selectQuizAnswerMatrix(qi, li, val) {
  const st = quizPlayerState; if (!st || st.submitted) return;
  let arr = Array.isArray(st.answers[qi]) ? st.answers[qi].slice() : [];
  if (val === '') delete arr[li]; else arr[li] = parseInt(val, 10);
  st.answers[qi] = arr;
  persistQuizAnswers();
  updateQuizQuestionCard(qi);
  updateQuizProgressUI();
}
function selectQuizAnswer(qi, oi) { selectQuizAnswerMulti(qi, oi, true, 'single'); }

/* ============================================================
   PREVIEW (admin) — same shell, no proctoring
   ============================================================ */

function previewQuizPaper() {
  quizPaperConfig = {
    subject:    ($('qpSubject')?.value || '').trim(),
    paperCode:  ($('qpCode')?.value    || '').trim(),
    totalTime:  ($('qpTime')?.value    || '').trim(),
    totalMarks: parseInt($('qpMarks')?.value, 10) || 0
  };
  if (quizDraft.length === 0) return showToast('Add at least one question first.', 'info');

  const course = findCourse(quizEditingCourseId);
  const mat = (course.materials || []).find(m => m.id === quizEditingMaterialId);

  const emptyAnswer = q => q.type === 'integer' ? '' : [];
  const _previewOrder = Array.from({ length: quizDraft.length }, (_, i) => i);

  quizPlayerState = {
    courseId: quizEditingCourseId,
    materialId: quizEditingMaterialId,
    materialTitle: mat ? mat.title : 'Preview',
    quiz: JSON.parse(JSON.stringify(quizDraft)),
    answers: quizDraft.map(emptyAnswer),
    submitted: false,
    response: null,
    paperConfig: { ...quizPaperConfig },
    previewMode: true,
    examStarted: false,
    strikes: 0,
    violations: [],
    startTime: null,
    violationHandling: false,
    fullscreenArmed: true,

    /* ⭐ Preview honours the same policy the admin just configured */
    forwardOnly: quizPaperConfig.allowBackNavigation !== true,
    allowBackNavigation: quizPaperConfig.allowBackNavigation === true,
    showQuestionPalette: quizPaperConfig.showQuestionPalette !== false,
    questionOrder: _previewOrder,
    optionOrders: {},
    displayIndex: 0,
    serverStartedAt: Date.now(),
    durationSeconds: parseQuizTime(quizPaperConfig.totalTime),
    timeSpentPerQuestion: {},
    questionLocked: {}
  };

  const shell = document.getElementById('quizExamShell');
  if (!shell) return;
  shell.style.display = 'flex';
  shell.setAttribute('aria-hidden', 'false');
  document.body.style.overflow = 'hidden';
  renderQuizExamShell();
}

/* ============================================================
   Shared guard — throws if this material is premium and locked.
   Called FIRST in every open-* function. No network calls are
   made until this returns true.
   ============================================================ */
function assertMaterialUnlocked(courseId, materialId, opts) {
  opts = opts || {};
  if (!currentUser) {
    if (!opts.silent) showToast('Please log in to open this material.', 'error');
    return false;
  }
  if (isAdmin(currentUser)) return true;

  const course = findCourse(courseId);
  if (!course) { if (!opts.silent) showToast('Course not found.', 'error'); return false; }

  const mat = (course.materials || []).find(m => m.id === materialId);
  if (!mat) { if (!opts.silent) showToast('Material not found.', 'error'); return false; }

  const isCoursePremium = course.isPremium === true || course.isPremium === 'true';
  const isMatPremium    = mat.isPremium    === true || mat.isPremium    === 'true';

  /* ⭐ FREE CONTENT — neither course nor material is premium.
     Always allow. This is the only case where purchase is NOT required. */
  if (!isCoursePremium && !isMatPremium) return true;

  const ownsCourse   = userOwnsItem(course.id);
  const ownsMaterial = userOwnsItem(mat.id);
  const subscribed   = !!currentUser.isSubscribed;

  if (subscribed || ownsCourse || ownsMaterial) return true;

  if (!opts.silent) {
    showToast('This content is locked. Purchase it or subscribe to unlock.', 'error');
  }
  return false;
}
/* ============================================================
   ⭐ _detectDocumentKind — classify a non-PDF file by its name
      or URL so viewFileOnline() can route it to the correct
      viewer. Pure function; never mutates state.
   ============================================================ */
function _detectDocumentKind(fileName, url) {
  const hay = (String(fileName || '') + ' ' + String(url || ''))
    .toLowerCase().split('?')[0].split('#')[0];
  const m = hay.match(/\.([a-z0-9]{1,6})(?:\s|$|\/|&|,)/);
  const ext = m ? m[1] : '';
  if (['pptx','ppt','ppsx','pps','potx','pot'].includes(ext))  return 'presentation';
  if (['docx','doc','rtf','odt'].includes(ext))                return 'document';
  if (['xlsx','xls','csv','ods'].includes(ext))                return 'spreadsheet';
  if (['png','jpg','jpeg','gif','webp','avif','bmp','svg'].includes(ext)) return 'image';
  if (['txt','md','log','json','xml','yaml','yml','ini'].includes(ext))   return 'text';
  return 'unknown';
}

/* ============================================================
   viewFileOnline — PREMIUM + PREVIEW GATED, STREAMING-FIRST
   ------------------------------------------------------------
   Optimized loading pipeline:

     ①  Client-side gate (no network) — skip obviously-locked items
     ②  Parallel:  fetch /file?meta=1  +  start loading PDF.js
     ③  If the PDF lives on disk (or a public URL), stream it via
        pdfjsLib.getDocument({ url }) so PDF.js can use HTTP range
        requests and render page 1 without waiting for the whole file.
     ④  Fallback to the legacy base64 endpoint only when streaming
        is not possible (no disk file, no public URL).

   Result: first page typically visible in < 1 s on broadband,
   and in < 2 s even on a slow 4G connection for a 20 MB PDF.
   ============================================================ */
/* ============================================================
   viewFileOnline — PREMIUM + PREVIEW GATED, STREAMING-FIRST
   ------------------------------------------------------------
   v3 — the SERVER is the single source of truth.

   Bug fixed: the old version gated on `getMaterialAccessInfo()`
   BEFORE fetching `?meta=1`. If the client's cached course list
   lacked `previewPercent` (which it did — see the /api/courses
   projection fix), `access.canPreview` was always false, so the
   viewer either blocked or opened with previewPercent: 0 and
   showed the blank "locked" card even when the server had a
   real preview configured.

   Now:
     ① Fetch `?meta=1` FIRST.
     ② Let the meta response decide open / block.
     ③ Use meta's hasFullAccess + previewPercent in the viewer.
     ④ Fall back to client-side access only if meta is unreachable.
   ============================================================ */
/* ============================================================
   ⭐ OFFICE FILES → IN-APP VIEWER (2026-10-04)
   Asks the server for a rendered PDF of the PowerPoint / Word /
   Excel file (first open may take a few seconds while it's
   converted), then opens it in the protected PDF viewer.
   ============================================================ */
let _renderOverlayEl = null;
let _renderSession = 0;          // bumped on every open / cancel — a stale poll loop stops itself
function _showRenderOverlay(title, kind) {
  _hideRenderOverlay();
  const el = document.createElement('div');
  el.className = 'render-overlay';
  el.setAttribute('role', 'status');
  el.innerHTML = `
    <div class="render-card">
      <div class="render-icon"><i class="fas ${kind === 'presentation' ? 'fa-person-chalkboard' : kind === 'spreadsheet' ? 'fa-table' : 'fa-file-lines'}"></i></div>
      <strong>${kind === 'presentation' ? 'Preparing slides…' : 'Preparing document…'}</strong>
      <span>${escapeHtml(title || '')}</span>
      <div class="render-bar"><i></i></div>
      <small class="render-note">The first opening can take a few seconds.</small>
      <button type="button" class="btn btn-outline btn-sm render-cancel">Cancel</button>
    </div>`;
  el.querySelector('.render-cancel').addEventListener('click', () => { _renderSession++; _hideRenderOverlay(); });
  document.body.appendChild(el);
  requestAnimationFrame(() => el.classList.add('active'));
  _renderOverlayEl = el;
}
function _setRenderOverlayNote(text) {
  const n = _renderOverlayEl && _renderOverlayEl.querySelector('.render-note');
  if (n) n.textContent = text;
}
function _hideRenderOverlay() {
  if (_renderOverlayEl) { const e = _renderOverlayEl; _renderOverlayEl = null; e.classList.remove('active'); setTimeout(() => e.remove(), 200); }
}

/* Office files are converted on the server the first time they are
   opened. The server answers within ~20 s either with the ready file
   or with "still preparing" (HTTP 202) — we simply ask again until it
   is ready, so a big deck never runs into a proxy time-out. */
async function openRenderedOfficeFile(course, mat, meta, pdfJsPromise) {
  const kind = _detectDocumentKind(mat.fileName || (meta && meta.fileName) || '', mat.url || '');
  _showRenderOverlay(mat.title, kind === 'unknown' ? 'presentation' : kind);
  const session = ++_renderSession;
  const cancelled = () => session !== _renderSession;
  const started = Date.now();
  const MAX_WAIT_MS = 6 * 60 * 1000;
  const endpoint = `${API_BASE}/courses/${course.id}/materials/${mat.id}/render`;
  let data = null;
  let transientErrors = 0;
  pdfJsPromise.catch(() => null);
  while (true) {
    if (cancelled()) return;
    try {
      data = await fetchJSON(`${endpoint}?wait=20000&_t=${Date.now()}`);
      transientErrors = 0;
    } catch (e) {
      /* Network blip or a proxy error page (502/503/504): the conversion
         keeps running on the server — try again a few times. */
      const msg = String((e && e.message) || '');
      transientErrors++;
      if (transientErrors > 4 || !/network|HTTP 50[234]|empty response/i.test(msg)) {
        _hideRenderOverlay();
        return showToast(msg || 'Could not open this file.', 'error');
      }
      data = { pending: true, retryAfter: 3 };
    }
    if (cancelled()) return;
    if (data && data.success && data.url) break;
    if (!(data && data.pending)) break;
    const waited = Date.now() - started;
    if (waited > MAX_WAIT_MS) {
      _hideRenderOverlay();
      return showToast('This file is taking unusually long to prepare. Please try again in a few minutes.', 'error');
    }
    _setRenderOverlayNote(waited < 25000
      ? 'Converting for the in-app viewer — large files take a little longer the first time.'
      : `Still preparing… ${Math.round(waited / 1000)} s (this happens only on the first opening).`);
    await new Promise(r => setTimeout(r, Math.max(1, Number(data.retryAfter) || 2) * 1000));
  }
  if (cancelled()) return;

  try { await pdfJsPromise; } catch (_) {}
  _hideRenderOverlay();
  if (!data || !data.success || !data.url) {
    return showToast((data && data.message) || 'Could not open this file.', 'error');
  }
  if (!window.pdfjsLib || !window.PDFViewer) return showToast('Could not load the viewer. Please refresh the page.', 'error');

  window.PDFViewer.open({
    url:            data.url,
    materialId:     mat.id,
    courseId:       course.id,
    title:          mat.title,
    mode:           data.kind === 'presentation' ? 'slides' : 'document',
    username:       currentUser
                      ? (currentUser.fullName || currentUser.username || 'Student')
                      : 'Guest · ' + new Date().toLocaleString('en-IN', { timeZone: 'Asia/Kolkata' }),
    hasFullAccess:  data.hasFullAccess === true,
    previewPercent: data.hasFullAccess ? 0 : (Number(data.previewPercent) || 0),
    lockReason:     (meta && meta.reason) || null
  });
}

async function viewFileOnline(courseId, materialId) {
  const course = findCourse(courseId);
  if (!course) return showToast('Course not found.', 'error');

  const mat = (course.materials || []).find(m => m.id === materialId);
  if (!mat) return showToast('Material not found.', 'info');

  /* Client-side access is only used as a FALLBACK if meta fails. */
  const access = getMaterialAccessInfo(course, mat);

  /* ① Kick off PDF.js load + meta fetch in PARALLEL.
     We ALSO warm the /uploads/ connection with a tiny HEAD so the
     campus proxy has already negotiated the TCP + TLS handshake
     by the time the real GET fires. Fire-and-forget — never blocks. */
  const pdfJsPromise = window.loadPDFJS().catch(err => {
    console.warn('[viewFileOnline] PDF.js load failed:', err);
    throw err;
  });

  /* ⭐ Non-blocking warm-up of the uploads route. */
  try {
    const warmUrl = (mat.url && String(mat.url).startsWith('/uploads/'))
      ? String(mat.url)
      : null;
    if (warmUrl) {
      fetch(warmUrl, {
        method: 'HEAD',
        credentials: 'same-origin',
        cache: 'default',
        priority: 'low',
        keepalive: true
      }).catch(() => {});
    }
  } catch (_) { /* purely an optimisation — never break the flow */ }

  let meta = null;
  let metaFailed = false;
  try {
    meta = await fetchJSON(
      `${API_BASE}/courses/${courseId}/materials/${materialId}/file?meta=1&_t=${Date.now()}`
    );
  } catch (err) {
    console.warn('[viewFileOnline] meta check failed:', err.message);
    metaFailed = true;
    meta = null;
  }

  /* ② If meta explicitly refused, surface the reason */
  if (meta && meta.success === false) {
    if (meta.code === 'login-required' || meta.requiresLogin) {
      return showToast('Please log in to open this material.', 'error');
    }
    if (meta.code === 'course-premium' || meta.code === 'material-premium') {
      return showToast(meta.message || 'This content is locked.', 'error');
    }
    return showToast(meta.message || 'Could not open this material.', 'error');
  }

  /* ③ Resolve the final access state.
     Prefer the server's numbers when available; fall back to the
     client's local evaluation only if the meta call failed. */
  const hasFullAccess  = meta
    ? (meta.hasFullAccess === true)
    : (access.hasFullAccess === true);

  const previewPercent = meta
    ? (meta.hasFullAccess ? 0 : (Number(meta.previewPercent) || 0))
    : (access.hasFullAccess ? 0 : (Number(access.previewPercent) || 0));

  const lockReason = meta ? (meta.reason || null) : null;

  /* ④ If there is genuinely NO access at all (no full + no preview),
     do NOT open the viewer — show a clear toast instead.
     This avoids the "opens then immediately shows locked" jank. */
  if (!hasFullAccess && previewPercent <= 0) {
    if (!currentUser || (meta && meta.requiresLogin)) {
      return showToast('Please log in to open this material.', 'error');
    }
    if (meta && meta.isCoursePremium) {
      return showToast('Purchase the course to access this material.', 'error');
    }
    return showToast('This content is locked. Purchase it to unlock.', 'error');
  }

  /* ⑤ Choose the best source (streaming preferred) */
  const serverFileUrl = (meta && meta.fileUrl) ? String(meta.fileUrl).trim() : '';
  const fileName = mat.fileName || (meta && meta.fileName) || '';
  const isPdf = String(fileName).toLowerCase().endsWith('.pdf') ||
                serverFileUrl.toLowerCase().split('?')[0].endsWith('.pdf');

  const isDiskUrl     = serverFileUrl.startsWith('/uploads/');
  const isExternalUrl = /^https?:\/\//i.test(serverFileUrl);
  const canStream     = isPdf && (
                        (isDiskUrl && meta && meta.diskFileExists === true) ||
                        isExternalUrl
                      );

  /* ⑤a STREAMING PATH — the fast one */
  if (canStream) {
    try { await pdfJsPromise; }
    catch { return showToast('Could not load PDF viewer.', 'error'); }

    /* ⭐ For preview-only users, request the TRUNCATED preview PDF
       (already generated server-side at upload time). It contains
       only the free pages, so it is 5–10× smaller than the full
       document — a major win on a slow campus link. */
    let effectiveUrl = serverFileUrl;
    if (!hasFullAccess && previewPercent > 0 && isDiskUrl) {
      // Swap the filename for its `.preview` sibling, keeping query.
      const [pathPart, queryPart] = effectiveUrl.split('?');
      if (!pathPart.endsWith('.preview')) {
        effectiveUrl = pathPart + '.preview' + (queryPart ? '?' + queryPart : '');
      }
    }

    const url = (meta && meta.signedUrl)
      ? effectiveUrl
      : (isDiskUrl ? withAuthToken(effectiveUrl) : effectiveUrl);

    window.PDFViewer.open({
      url,
      materialId:     mat.id,
      courseId:       course.id,
      title:          mat.title,
      username:       currentUser
                        ? (currentUser.fullName || currentUser.username || 'Guest')
                        : 'Guest · ' + new Date().toLocaleString('en-IN', { timeZone: 'Asia/Kolkata' }),
      hasFullAccess,
      previewPercent,
      lockReason
    });
    return;
  }

    /* ============================================================
       ⑤b  ⭐ NON-PDF MATERIALS → Universal DocumentViewer
       ------------------------------------------------------------
       Handles PPTX/PPT, DOCX/DOC, XLSX/XLS/CSV, images, and
       plain text. The PDF path above is completely unchanged;
       this block only runs when isPdf is false.

       Design notes
       ------------
       • The signed URL (fileUrl from /file?meta=1) is used so
         Microsoft's Office viewer can fetch the file. For users
         without full access the file is not signed, so we show
         the same lock message the PDF path already uses.
       • Office formats cannot be physically truncated for a
         free preview, so they are treated as fully locked when
         the user does not own the content.
       • Falls through to a clean "Preview unavailable" toast
         for unknown formats rather than a misleading error.
       ============================================================ */
    /* ⭐ PowerPoint / Word / Excel → rendered on the server to a protected
       PDF and shown in the in-app viewer (slideshow for presentations).
       The original file is never downloaded. */
    if (!isPdf && meta && meta.renderable) {
      return openRenderedOfficeFile(course, mat, meta, pdfJsPromise);
    }
    /* Older server, or the meta call failed: any PowerPoint / Word / Excel
       file still goes to the in-app renderer — never to the external
       DocumentViewer, which cannot show protected office files. */
    {
      const _k = _detectDocumentKind(fileName, serverFileUrl || mat.url || '');
      if (!isPdf && (_k === 'presentation' || _k === 'document' || _k === 'spreadsheet') &&
          !/\.(csv)(\?|$)/i.test(String(fileName || serverFileUrl || ''))) {
        return openRenderedOfficeFile(course, mat, meta, pdfJsPromise);
      }
    }

    if (!isPdf && (isDiskUrl || isExternalUrl)) {
      const _docKind = _detectDocumentKind(fileName, serverFileUrl);

      if (_docKind === 'unknown') {
        return showToast('Preview is not available for this file format.', 'info');
      }

      const _isOfficeDoc = _docKind === 'presentation' ||
                           _docKind === 'document'     ||
                           _docKind === 'spreadsheet';

      /* Office documents need a publicly-reachable signed URL
         for Microsoft's servers. Without full access there is no
         signed URL, so we show the same lock toast as PDFs. */
      if (_isOfficeDoc && !hasFullAccess) {
        if (!currentUser || (meta && meta.requiresLogin)) {
          return showToast('Please log in to open this material.', 'error');
        }
        if (meta && meta.isCoursePremium) {
          return showToast('Purchase the course to access this material.', 'error');
        }
        return showToast('This content is locked. Purchase it to unlock.', 'error');
      }

      /* Guard: DocumentViewer must have loaded. It's `defer`ed, so
         it should already be present by the time a user clicks. */
      if (!window.DocumentViewer || typeof window.DocumentViewer.open !== 'function') {
        return showToast('Document viewer is still loading. Please try again.', 'info');
      }

      /* Prefer the URL the server already signed (has ?su=&st=).
         Fall back to the raw URL if signing was not applicable. */
      let _viewUrl = (meta && meta.fileUrl) ? String(meta.fileUrl) : serverFileUrl;
if (_viewUrl.startsWith('/')) {
  _viewUrl = window.location.origin + _viewUrl;
}

      window.DocumentViewer.open({
        url:            _viewUrl,
        fileName:       fileName,
        title:          mat.title,
        docType:        _docKind,
        courseId:       course.id,
        materialId:     mat.id,
        hasFullAccess:  hasFullAccess,
        previewPercent: previewPercent,
        lockReason:     lockReason,
        username:       currentUser
                          ? (currentUser.fullName || currentUser.username || 'Student')
                          : 'Guest'
      });
      return;
    }

  /* ⑤c LEGACY BASE64 FALLBACK — only when streaming isn't possible */
  try { await pdfJsPromise; }
  catch { return showToast('Could not load PDF viewer.', 'error'); }

  try {
    const check = await fetchJSON(
      `${API_BASE}/courses/${courseId}/materials/${materialId}/file?_t=${Date.now()}`
    );

    if (check && check.success === false &&
        (check.code === 'course-premium' ||
         check.code === 'material-premium' ||
         check.code === 'login-required')) {
      return showToast(check.message || 'This content is locked.', 'error');
    }

    if (check && check.success && check.fileData) {
      const fd = check.fileData;
      const viewerOpts = {
        materialId:     mat.id,
        courseId:       course.id,
        fileName:       fileName,
        title:          mat.title,
        username:       currentUser
                          ? (currentUser.fullName || currentUser.username || 'Guest')
                          : 'Guest · ' + new Date().toLocaleString('en-IN', { timeZone: 'Asia/Kolkata' }),
        hasFullAccess:  check.hasFullAccess === true,
        previewPercent: check.previewPercent || 0,
        lockReason
      };

      if (String(fd).startsWith('data:')) {
        viewerOpts.data = fd;
      } else if (/^https?:\/\//i.test(fd) || fd.startsWith('/uploads/')) {
        viewerOpts.url = withAuthToken(fd);
      } else {
        viewerOpts.data = fd;
      }
      window.PDFViewer.open(viewerOpts);
      return;
    }
  } catch (e) {
    console.warn('[viewFileOnline] legacy fallback failed:', e.message);
    if (/locked|premium|subscription|purchase|login/i.test(e.message || '')) {
      return showToast(e.message, 'error');
    }
  }

  showToast('No file attached.', 'info');
}

/* ============================================================
   ⭐ VIDEO WATCH PROGRESS (2026-10-04)
   ------------------------------------------------------------
   • The player (media-viewer.js) fires `aero:video-progress`
     events; we persist them via POST /api/user/video-progress.
   • Course pages load the student's map once per minute and
     draw per-video bars, playlist completion and "Resume" labels.
   • Reaching 90 % auto-marks the material as completed (same
     XP / streak path as the manual "Mark done" button).
   ============================================================ */
const AeroVideoProgress = (function () {
  const store = Object.create(null);           // materialId → {pos,dur,pct,completed,updatedAt}
  const loadedAt = new Map();                  // courseId → ms
  const inflight = new Map();
  const LOAD_TTL_MS = 60 * 1000;

  function isStudent() {
    return !!(currentUser && String(currentUser.role || '').toLowerCase() === 'student');
  }
  function get(mid) { return mid ? (store[mid] || null) : null; }

  /* Resolves true when fresh data arrived (caller may re-render). */
  function ensure(courseId) {
    if (!isStudent() || !courseId) return Promise.resolve(false);
    const at = loadedAt.get(courseId) || 0;
    if (Date.now() - at < LOAD_TTL_MS) return Promise.resolve(false);
    if (inflight.has(courseId)) return inflight.get(courseId);
    loadedAt.set(courseId, Date.now());
    const p = fetch(`${API_BASE}/user/video-progress?courseId=${encodeURIComponent(courseId)}`, { cache: 'no-store' })
      .then(r => r.ok ? r.json() : null)
      .then(d => {
        if (!d || !d.success || !d.progress) return false;
        let changed = false;
        Object.keys(d.progress).forEach(mid => {
          const prev = store[mid];
          const next = d.progress[mid];
          if (!prev || prev.pct !== next.pct || prev.completed !== next.completed || prev.pos !== next.pos) changed = true;
          store[mid] = next;
        });
        return changed;
      })
      .catch(() => false)
      .finally(() => inflight.delete(courseId));
    inflight.set(courseId, p);
    return p;
  }

  async function report(detail) {
    if (!isStudent() || !detail || !detail.materialId || !detail.courseId) return;
    /* Optimistic local update so bars move immediately */
    const cur = store[detail.materialId] || { pos: 0, dur: 0, pct: 0, completed: false };
    const pct = detail.ended ? 100 : (detail.duration > 0 ? Math.round(detail.position / detail.duration * 100) : 0);
    store[detail.materialId] = {
      pos: detail.ended ? 0 : Math.round(detail.position),
      dur: Math.round(detail.duration),
      pct: Math.max(cur.pct || 0, Math.min(100, pct)),
      completed: cur.completed || pct >= 90,
      updatedAt: new Date().toISOString()
    };
    try {
      const res = await fetch(`${API_BASE}/user/video-progress`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        keepalive: detail.reason === 'close',
        body: JSON.stringify({
          courseId: detail.courseId, materialId: detail.materialId,
          position: detail.position, duration: detail.duration, ended: !!detail.ended
        })
      });
      const data = await res.json().catch(() => null);
      if (data && data.success && data.progress) {
        store[detail.materialId] = Object.assign({}, store[detail.materialId], data.progress);
        if (data.completedNow && !isMaterialViewed(detail.courseId, detail.materialId)) {
          markMaterialViewedQuietly(detail.courseId, detail.materialId);
        }
      }
    } catch (e) { /* offline — localStorage resume still works */ }
  }

  return { get, ensure, report, _store: store };
})();
window.AeroVideoProgress = AeroVideoProgress;

window.addEventListener('aero:video-progress', (e) => { AeroVideoProgress.report(e.detail); });
window.addEventListener('aero:video-closed', () => {
  /* Repaint bars / "Up next" once the player is gone */
  if (window.currentSelectedCourseId || currentCourseId) {
    try { renderApp(); } catch (e) {}
  }
});

/* Same server path as the "Mark done" button, without the toast/re-render
   storm — used when a video crosses the 90 % mark. */
async function markMaterialViewedQuietly(courseId, materialId) {
  try {
    const res = await fetch(`/api/user/progress/${courseId}/${materialId}`, {
      method: 'POST', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ userId: currentUser._id, viewed: true })
    });
    const data = await res.json();
    if (data && data.success) {
      currentUser.progress = data.progress;
      currentUser.lastActivity = data.lastActivity;
      if (data.streakCount !== undefined) currentUser.streakCount = data.streakCount;
      if (data.longestStreak !== undefined) currentUser.longestStreak = data.longestStreak;
      saveSessionUser(currentUser);
      showToast('✅ Lecture completed — progress saved', 'success');
    }
  } catch (e) { /* non-fatal */ }
}

function _fmtClock(sec) {
  sec = Math.max(0, Math.floor(Number(sec) || 0));
  const h = Math.floor(sec / 3600), m = Math.floor((sec % 3600) / 60), s2 = sec % 60;
  return (h ? h + ':' + String(m).padStart(2, '0') : m) + ':' + String(s2).padStart(2, '0');
}

/* Small progress strip under a video card's title */
function videoProgressStripHtml(materialId) {
  const pr = AeroVideoProgress.get(materialId);
  if (!pr || (!pr.pct && !pr.completed)) return '';
  const pct = pr.completed ? 100 : Math.max(2, Math.min(100, pr.pct || 0));
  const label = pr.completed
    ? '<i class="fas fa-check-circle"></i> Watched'
    : `${pct}% watched${pr.pos >= 10 ? ' · resume at ' + _fmtClock(pr.pos) : ''}`;
  return `<div class="vprog ${pr.completed ? 'done' : ''}" role="progressbar" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${pct}" aria-label="Watch progress">
      <div class="vprog-bar"><span style="width:${pct}%"></span></div>
      <div class="vprog-label">${label}</div>
    </div>`;
}

/* Playlist completion summary */
function playlistProgress(course, pl) {
  const ids = (pl.materialIds || []).filter(id => (course.materials || []).some(m => m.id === id));
  let done = 0, sum = 0, firstUnfinished = -1;
  ids.forEach((id, i) => {
    const pr = AeroVideoProgress.get(id);
    const viewed = isMaterialViewed(course.id, id);
    const finished = !!(pr && pr.completed) || viewed;
    if (finished) done++;
    sum += finished ? 100 : (pr ? (pr.pct || 0) : 0);
    if (!finished && firstUnfinished < 0) firstUnfinished = i;
  });
  return {
    total: ids.length, done,
    pct: ids.length ? Math.round(sum / ids.length) : 0,
    resumeIndex: firstUnfinished < 0 ? 0 : firstUnfinished,
    started: sum > 0
  };
}

/* Course-level progress + the next thing to study (in course order) */
function courseProgressSummary(course) {
  const mats = acOrderedMaterials(course);
  const viewedIds = getProgress(course.id);
  const done = mats.filter(m => viewedIds.includes(m.id)).length;
  let next = null;
  for (const m of mats) {
    if (viewedIds.includes(m.id)) continue;
    next = m; break;
  }
  return { done, total: mats.length, pct: mats.length ? Math.round(done / mats.length * 100) : 0, next };
}

function openMaterialSmart(courseId, materialId) {
  const course = findCourse(courseId);
  const m = course && (course.materials || []).find(x => x.id === materialId);
  if (!m) return;
  const isVideoUrl = m.type === 'video' && (m.url || m.cloudUrl) && !(m.fileName || m.diskName);
  if (isVideoUrl) openMaterialVideo(courseId, materialId);
  else viewFileOnline(courseId, materialId);
}

/* ============================================================
   openMaterialVideo — PREMIUM GATED
   ============================================================ */
async function openMaterialVideo(courseId, materialId) {
  if (!assertMaterialUnlocked(courseId, materialId)) return;

  const course = findCourse(courseId);
  if (!course) return;
  const mat = (course.materials || []).find(m => m.id === materialId);
  if (!mat || !mat.url) return showToast('No video URL set for this material.', 'error');

  /* Make sure the server-side resume point is known (≤ 1 request/min) */
  try { await Promise.race([AeroVideoProgress.ensure(courseId), new Promise(r => setTimeout(r, 800))]); } catch (e) {}

  /* ⭐ Store context so heartbeats know exactly what's playing */
  window.__activeVideoContext = {
    courseId,
    materialId,
    title: mat.title || ''
  };

  try {
    const res = await fetch(
      `/api/materials/${courseId}/${materialId}/video-session`,
      {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ userId: currentUser._id })
      }
    );
    const data = await res.json();

    if (!data.success) {
      window.__activeVideoContext = null;
      return showToast(data.message || 'Could not load video.', 'error');
    }

    const baseOpts = {
      materialId: mat.id,
      courseId: course.id,
      title: mat.title,
      username: currentUser.fullName || currentUser.username || 'Student'
    };

    if (data.kind === 'youtube' && data.videoId) {
      window.VideoPlayer.open({ ...baseOpts, videoId: data.videoId });
    } else if (data.kind === 'direct' && data.directUrl) {
      window.VideoPlayer.open({ ...baseOpts, src: withAuthToken(data.directUrl) });
    } else {
      window.__activeVideoContext = null;
      showToast('Unsupported video response from server.', 'error');
    }
  } catch (e) {
    window.__activeVideoContext = null;
    showToast('Server error loading video.', 'error');
  }
}

async function toggleBookmark(e, courseId) {
  if (e) e.stopPropagation();
  if (!currentUser?._id) return;
  try {
    const res = await fetch(`/api/user/bookmarks/${courseId}`, {
      method: 'POST', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ userId: currentUser._id })
    });
    const data = await res.json();
    if (data.success) {
      currentUser.bookmarks = data.bookmarks;
      saveSessionUser(currentUser);
      showToast(data.bookmarked ? '★ Saved' : 'Removed', 'success');
      renderApp();
    } else showToast(data.message || 'Failed.', 'error');
  } catch { showToast('Server error.', 'error'); }
}

async function toggleMaterialViewed(e, courseId, materialId) {
  if (e) e.stopPropagation();
  const currently = isMaterialViewed(courseId, materialId);
  try {
    const res = await fetch(`/api/user/progress/${courseId}/${materialId}`, {
      method: 'POST', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ userId: currentUser._id, viewed: !currently })
    });
    const data = await res.json();
    if (data.success) {
      currentUser.progress = data.progress;
      currentUser.lastActivity = data.lastActivity;
      if (data.streakCount !== undefined) currentUser.streakCount = data.streakCount;
      if (data.longestStreak !== undefined) currentUser.longestStreak = data.longestStreak;
      if (data.lastActiveDate) currentUser.lastActiveDate = data.lastActiveDate;
      saveSessionUser(currentUser);
      renderApp();
    } else showToast(data.message || 'Failed.', 'error');
  } catch { showToast('Server error.', 'error'); }
}

/* ⚡ Throttle — ensures we only hit /api/user/me at most once every
   20 s per session. Course-navigation flows used to fire this on
   every click; under traffic that's thousands of redundant reads. */
let _lastRefreshUserDataAt = 0;
const REFRESH_USER_DATA_MIN_MS = 20000;

async function refreshUserData(force = false) {
  if (!currentUser?._id) {
    console.warn('[refreshUserData] ❌ No currentUser._id — aborting');
    return;
  }

  if (!force) {
    const now = Date.now();
    if (now - _lastRefreshUserDataAt < REFRESH_USER_DATA_MIN_MS) {
      return;
    }
    _lastRefreshUserDataAt = now;
  } else {
    _lastRefreshUserDataAt = Date.now();
  }

  const userIdAtStart = currentUser._id;

  try {
    const url = `${API_BASE}/user/me/${userIdAtStart}?_t=${Date.now()}`;
    console.log('[refreshUserData] 🔄 Fetching', url);

    const res = await fetch(url, { cache: 'no-store' });
    console.log('[refreshUserData] 📥 HTTP', res.status);

    if (!res.ok) {
      console.warn('[refreshUserData] ❌ Non-OK status:', res.status);
      return;
    }

    const data = await res.json();
    console.log('[refreshUserData] 📦 Response:', {
      success: data.success,
      hasUser: !!data.user,
      purchaseCount: Array.isArray(data.user && data.user.purchases)
        ? data.user.purchases.length
        : 'n/a',
      purchases: data.user && data.user.purchases
    });

    if (!data.success) {
      console.warn('[refreshUserData] ❌ Server said not success:', data.message);
      return;
    }

    if (!currentUser || currentUser._id !== userIdAtStart) {
      console.warn('[refreshUserData] ⚠️ User changed during fetch — skipping');
      return;
    }
    if (_sessionKilled) {
      console.warn('[refreshUserData] ⚠️ Session killed — skipping');
      return;
    }

    /* ⭐ RankerNode — a category chosen while this request was in
       flight wins over the (older) server copy. */
    if (typeof _acChosenAt === 'number' && Date.now() - _acChosenAt < 20000 && data.user) {
      data.user.examCategory = currentUser.examCategory || '';
    }
    currentUser = data.user;
    saveSessionUser(currentUser);
    console.log('[refreshUserData] ✅ Updated. Purchases count:',
                (currentUser.purchases || []).length);
  } catch (e) {
    console.warn('[refreshUserData] ❌ Fetch failed:', e && e.message);
  }
}

